export declare const CapabilityEnableStatus: {
  /** A current activation is available, including a previously enabled entry. */ readonly enabled: 'enabled';
  /** The entry's flag denies activation when the outcome is classified. */ readonly gated: 'gated';
  /** Activation lost ownership through disable, disposal, or a newer attempt. */ readonly cancelled: 'cancelled';
  /** The current attempt failed and supplies its error in the result. */ readonly failed: 'failed';
};

export declare const CapabilityErrorCode: {
  /** * Thrown when a mutation method such as `register`, `setFlag`, `setFlags`, `enable`, or `disable` * is called after the host is disposed. * * Enforces the terminal host boundary. Read-only diagnostics (`names`, `state`, `handle`, and * `error`) remain available after disposal. Create a new host to enable capabilities again. A * disposed host cannot be revived. */ readonly hostDisposed: 'HOST_DISPOSED';
  /** * Thrown or rejected when `register`, `setFlag`, `setFlags`, `enable`, `disable`, or `dispose` * reenters a disposer or reporter while `transitionDepth > 0`. Also rejects repeated `dispose()` * calls before the first disposal completes. * * Enforces the reentrancy boundary. A rollback callback cannot rewrite the flag snapshot during * the surrounding transition. Move mutations outside lifecycle callbacks. */ readonly hostTransitioning: 'HOST_TRANSITIONING';
  /** * Thrown when `state`, `handle`, `error`, `enable`, or `disable` references an unregistered * capability. * * Enforces registered-name lookup. Check the name and register the capability first. */ readonly notRegistered: 'NOT_REGISTERED';
  /** * Thrown when `register()` receives an existing `name`. Duplicate registration is a programming * error and never silently replaces the existing entry. * * Enforces unique registration names. Use a different name or create a new host. */ readonly alreadyRegistered: 'ALREADY_REGISTERED';
  /** * Thrown as a `TypeError` when `register()` receives a name that is not a nonempty string. * * Enforces input validation. Correct `name` before retrying. */ readonly invalidName: 'INVALID_NAME';
  /** * Thrown as a `TypeError` when `register()` receives a non-function `activate`. * * Enforces input validation. Provide a callable `activate`. */ readonly invalidActivate: 'INVALID_ACTIVATE';
  /** * Thrown as a `TypeError` when the result of `activate()` lacks a callable `dispose`. Rejects * incomplete activation instead of leaving a partially enabled capability. * * Enforces the handle contract. Ensure `activate` returns a handle with `dispose`. */ readonly invalidHandle: 'INVALID_HANDLE';
  /** * Reserved for diagnostics or events when the gate denies activation. No current throw site uses * it. `enable()` returns `{ status: 'gated' }` for a denied activation without throwing. * Reserving this code for an `onError` or event channel does not change that behavior. * * Enforces the activation gate. `gated` differs from graph availability `blocked`. Branch on the * return value instead of catching an error. */ readonly gated: 'GATED';
  /** * Thrown when an `ownKeys`, `getOwnPropertyDescriptor`, or getter operation fails while * snapshotting `flags`, `definition`, or graph-readiness state/error, for example on a hostile * proxy. Annotatable readiness getter Errors retain their native identity and receive this code. * * The gate fails closed before throwing. `cause` retains the original proxy exception by * identity. Correct the flags or definition object before retrying. */ readonly invalidOption: 'INVALID_OPTION';
};

export declare const CapabilityState: {
  /** Allowed by the flag but not currently active. */ readonly off: 'off';
  /** Denied by the flag; enabling returns a gated outcome without activation. */ readonly gated: 'gated';
  /** One current activation is pending and may still be invalidated. */ readonly activating: 'activating';
  /** The current activation's handle has been adopted. */ readonly on: 'on';
  /** The current activation failed; error(name) retains its reason until a new transition. */ readonly failed: 'failed';
