export type ICapabilityHost<Context> = {
  /** * Captures a name and activation function without activating. Duplicate names, malformed recipes, * disposed hosts, and synchronous lifecycle reentry fail with the corresponding host code. */ register<
    Handle extends ICapabilityHandle,
  >(
    definition: ICapabilityDefinition<Context, Handle>,
  ): void;
  /** Fresh registration-order name array; it is a snapshot, not the mutable registry. */ readonly names: readonly string[];
  /** Reads current lifecycle state; an unknown name throws NOT_REGISTERED, even after disposal. */ state(
    name: string,
  ): ICapabilityState;
  /** Returns the enabled handle or undefined; unknown names throw NOT_REGISTERED. */ handle<
    Handle extends ICapabilityHandle,
  >(
    name: string,
  ): Handle | undefined;
  /** * Returns the retained activation or release failure, or undefined. Starting a new attempt or * deactivating clears the prior diagnostic; unknown names throw NOT_REGISTERED. */ error(
    name: string,
  ): unknown;
  /** * Updates one flag. Disabling synchronously invalidates pending activation and releases the * handle. Enabling does not activate. A name may be configured before it is registered; the * setter does not wait for asynchronous cleanup. */ setFlag(
    name: string,
    enabled: boolean,
  ): void;
  /** * Atomically replaces all flags. Missing capabilities are denied, so removed keys cannot retain * an earlier true value. An unreadable snapshot gates every entry before INVALID_OPTION is * thrown. Accessor flags are not evaluated, and this setter does not await cleanup. */ setFlags(
    flags: Readonly<Record<string, boolean>>,
  ): void;
  /** * Activates the capability and returns its structured activation outcome. * * Concurrent in-flight calls share the exact Promise and one activation. A denied flag resolves * gated without activation; an already enabled entry resolves enabled. Activation failures * resolve failed, while unknown names, disposed hosts, and transition reentry reject. */ enable(
    name: string,
  ): Promise<ICapabilityEnableResult>;
  /** * Synchronously invalidates activation and releases the current handle, then waits for this * entry's in-flight activation and cleanup, including late results. Resolves true only if the * entry was on; pending activation cancellation returns false. Cleanup failures are reported. */ disable(
    name: string,
  ): Promise<boolean>;
  /** * Makes the host terminal and releases handles in reverse activation-completion order, then waits * for every in-flight activation and release. Cleanup failures are reported without stopping * other releases. Later calls fail with HOST_TRANSITIONING until the first completion Promise * settles; after completion they return that original Promise by identity. */ dispose(): Promise<void>;
  /** Becomes true synchronously when final disposal begins, before pending cleanup settles. */ readonly disposed: boolean;
};

export type ICapabilityHostOptions = {
  /** * Initial flag snapshot. The gate denies activation by default. Only own data properties whose * value is exactly `true` permit activation. * * The host copies this snapshot. Use `setFlag()` or `setFlags()` for later changes. Mutating the * input object cannot bypass the state machine. `setFlag(name, false)` atomically invalidates * pending activation and releases the current handle. A separate `disable()` call is * unnecessary. */ readonly flags?: Readonly<
    Record<string, boolean>
  >;
  /** * Reports activation or release failures; omitted by default. Reporter failures preserve gate * state and error(name) diagnostics and reach the shared terminal reporting channel. */ readonly onError?: (
    name: string,
    error: unknown,
  ) => void;
};

export type ICapabilityReadinessSource = {
  /** Availability to capture; only ready, blocked, or failed is admitted. */ readonly state: unknown;
  /** Paired diagnostic read after valid state; retained by reference without interpretation. */ readonly error:
    | unknown
    | undefined;
};

export type IGraphReadinessSnapshot = {
  /** Availability at capture time; later changes to the source are not observed. */ readonly state: GraphReadinessState;
  /** Exact diagnostic captured with the state; undefined is allowed for any admitted state. */ readonly error:
    | unknown
    | undefined;
};

export declare function snapshotGraphReadiness(
  source: ICapabilityReadinessSource,
): IGraphReadinessSnapshot;

export declare const CapabilityGraphErrorCode: {
  /** Graph mutation/query reaches terminal state; create a new graph. */ readonly graphDisposed: 'GRAPH_DISPOSED';
  /** Registration is attempted after readiness froze the static registry. */ readonly graphFrozen: 'GRAPH_FROZEN';
  /** A node, dependency, or start result fails structural admission. */ readonly invalidNode: 'GRAPH_INVALID_NODE';
  /** A second node uses an already registered ID. */ readonly duplicateNode: 'GRAPH_DUPLICATE_NODE';
  /** A dependency names a provider absent from the frozen registry. */ readonly unknownProvider: 'GRAPH_UNKNOWN_PROVIDER';
  /** A consumer repeats the same provider edge. */ readonly duplicateEdge: 'GRAPH_DUPLICATE_EDGE';
  /** The required dependency graph contains a self-loop or cycle. */ readonly dependencyCycle: 'GRAPH_DEPENDENCY_CYCLE';
  /** A direct provider lookup is not declared and ready. */ readonly providerUnavailable: 'GRAPH_PROVIDER_UNAVAILABLE';
  /** A node start failed and the graph entered failed state. */ readonly startFailed: 'GRAPH_START_FAILED';
  /** Release of one or more graph-owned node resources failed. */ readonly disposeFailed: 'GRAPH_DISPOSE_FAILED';
  /** Startup or new work is rejected while the graph is quiescing. */ readonly admissionClosed: 'GRAPH_ADMISSION_CLOSED';
  /** Diagnostic or direct value query names an absent node; correct the id before retrying. */ readonly unknownNode: 'GRAPH_UNKNOWN_NODE';
  /** A lifecycle callback synchronously re-enters the same graph operation. */ readonly reentrantOperation: 'GRAPH_REENTRANT_OPERATION';
  /** * Factory options or ctx.own resource descriptors fail admission. Correct the input; ownership * failures retain the lifecycle native error on cause rather than reporting a closed graph. */ readonly invalidOption: 'GRAPH_INVALID_OPTION';
  /** A reject-policy mutation targets a node that still has required dependents. */ readonly nodeHasDependents: 'GRAPH_NODE_HAS_DEPENDENTS';
  /** * A dynamic-graph mutation waited behind an older mutation longer than `mutationAdmissionMs` and * was rejected without running. The lifecycle queue timeout stays on `cause`. Check for a stuck * predecessor (start that never settles, leaked binding lease) or raise the budget. */ readonly mutationAdmissionTimeout: 'GRAPH_MUTATION_ADMISSION_TIMEOUT';
  /** * `resume()` targets a dynamic-graph node that is not suspended. A state conflict, not a bad * option: suspend the node first, or skip the call when the node is already running. */ readonly nodeNotSuspended: 'GRAPH_NODE_NOT_SUSPENDED';
};

export declare const CapabilityGraphNodeState: {
  /** Definition is admitted but no instance is currently started. */ readonly registered: 'registered';
  /** Static startup is awaiting this node's primary instance. */ readonly starting: 'starting';
  /** The node's instance is available to permitted consumers. */ readonly ready: 'ready';
  /** Dynamic owner retained the instance while intentionally withholding service. */ readonly suspended: 'suspended';
  /** Startup or release failed with a retained diagnostic. */ readonly failed: 'failed';
  /** A provider or batch failure prevents service; a dynamic instance may still be retained. */ readonly blocked: 'blocked';
  /** Static startup or late-result cancellation relinquished this node's resources. */ readonly rolledBack: 'rolled-back';
  /** The static node's primary release completed. */ readonly released: 'released';
};

export declare const CapabilityGraphState: {
  /** Static registration is open, or a dynamic graph has not completed ready yet. */ readonly open: 'open';
  /** Static startup is running; external value visibility remains closed. */ readonly starting: 'starting';
  /** Readiness completed; individual dynamic nodes may still be unavailable. */ readonly ready: 'ready';
  /** Static startup failed and acquired resources were rolled back. */ readonly failed: 'failed';
  /** Disposal closed admission and is releasing graph-owned resources. */ readonly quiescing: 'quiescing';
  /** Final cleanup settled; create a new graph for further work. */ readonly terminal: 'terminal';
};

export declare function createCapabilityGraph(
  options?: ICapabilityGraphOptions,
): ICapabilityGraph;

examples:
import { createCapabilityGraph, type IGraphNodeId } from '@migaia/capability/graph'

const config = 'config' as IGraphNodeId
const screen = 'screen' as IGraphNodeId
const graph = createCapabilityGraph()
graph.register({
  id: screen,
  kind: 'view',
  dependencies: [{ provider: config, required: true }],
  start: (context) => {
    console.log('启动页面:', context.get<{ theme: string }>(config).theme)
    return {
      value: 'screen',
      release: () => {
        console.log('释放页面')
      }
    }
  }
})
graph.register({
  id: config,
  kind: 'service',
  dependencies: [],
  start: () => {
    console.log('启动配置')
    return {
      value: { theme: 'dark' },
      release: () => {
        console.log('释放配置')
      }
    }
  }
})
await graph.ready()
console.log('状态:', graph.state)
await graph.dispose()

import { createCapabilityGraph, type IGraphNodeId } from '@migaia/capability/graph'

const provider = 'config' as IGraphNodeId
const consumer = 'screen' as IGraphNodeId
const primary = new Error('页面启动失败')
const graph = createCapabilityGraph()
graph.register({
  id: provider,
  kind: 'service',
  dependencies: [],
  start: () => ({
    value: { theme: 'dark' },
    release: () => {
      console.log('回滚配置')
    }
  })
})
graph.register({
  id: consumer,
  kind: 'view',
  dependencies: [{ provider, required: true }],
  start: () => {
    throw primary
  }
})
try {
  await graph.ready()
} catch (error) {
  console.log('保留原错:', error === primary)
  console.log('错误码:', (error as Error & { code: string }).code)
}
console.log('提供方:', graph.nodeState(provider).state)
console.log('图状态:', graph.state)
await graph.dispose()

