function openChatPage(messages: EventTarget) {
  const page = createLifecycleScope()

  page.own('connection', { force: () => console.log('断开连接') })

  const onMessage = () => console.log('收到消息')
  messages.addEventListener('message', onMessage)
  page.own(onMessage, {
