export type IAsyncMiddlewareStage<TValue, TResult = void> = (
  value: TValue,
  next: (value: TValue) => Promise<TResult>,
  context?: IMiddlewarePipelineContext,
) => void | Promise<unknown>;

export type ICreatePipelineOptions<TMode extends IMiddlewarePipelineMode> = Readonly<{
  /** * Required execution mode: sync, async, generator, or async-generator. Determines stage shape, * downstream timing, and whether run throws synchronously or returns a promise. */ readonly mode: TMode;
  /** Number of values one active stage may submit; omitted preserves single semantics. */ readonly next?: MiddlewarePipelineNext;
  /** * Optional duplicate/late next reporter; defaults to a no-op. A rejected next never starts * downstream again. */ readonly onViolation?: IMiddlewarePipelineViolationHandler;
  /** * Optional host lifetime assertion at entry and after successful stages. Async onion frames also * check while returning, even after done ran; a later failure does not undo completed side * effects. */ readonly assertActive?: () => void;
  /** * Optional default cooperative signal. A supplied run-level signal overrides it; none is created * by default. */ readonly signal?: IAbortSignal;
  /** * Optional generator control symbols; defaults to MiddlewarePipelineGeneratorSignals. * undefined/halt/continue must be distinct symbols, read once and snapshotted at construction. */ readonly signals?: IGeneratorMiddlewareSignals;
  /** * Optional async-onion dual-failure policy, called with stage failure first and downstream * second. Without it, independent failures become EXECUTION_FAILED with both on * AggregateError.errors. A returned custom error must retain both originals through cause/errors; * a thrown combiner failure keeps the preexisting failures reachable. The same propagated object * is not combined twice. */ readonly combineStageAndDownstreamError?: (
    stage: unknown,
    downstream: unknown,
  ) => unknown;
}>;

export type IGeneratorMiddlewareSignals = {
  /** Explicitly forwards an undefined payload rather than halting on an ordinary undefined return. */ readonly undefined: symbol;
  /** Stops the run, including done, after this stage finishes. */ readonly halt: symbol;
  /** Forwards the last yield, or this stage's input if it yielded nothing. */ readonly continue: symbol;
};

export type IMiddlewarePipeline<
  TMode extends IMiddlewarePipelineMode,
  TValue,
  TSignals extends IGeneratorMiddlewareSignals =
    typeof MiddlewarePipelineGeneratorSignals,
> = Readonly<{
  /** Fixed construction mode; changing caller-owned options does not change it. */ readonly mode: TMode;
  /** * Adapts an allowed source stage to this runner's mode. Same-mode lifting returns the same * function; unsupported directions throw INVALID_OPTION. Lifted sync stages keep next as a local * value submission, so code after next still runs before downstream and a throw prevents * downstream entry. */ lift<
    TFrom extends IMiddlewarePipelineLiftSource<TMode>,
  >(
    stage: IMiddlewarePipelineStage<TFrom, TValue, TSignals>,
    from: TFrom,
  ): IMiddlewarePipelineStage<TMode, TValue, TSignals>;
  /** * Runs a snapshot of stages from value, calling done only if the sequence continues to the end. * control.signal optionally overrides the construction signal. An effective signal is supplied to * callbacks as context; cancellation is cooperative and never detaches already-started work. * Sync/generator failures throw; async modes reject after their started work settles. Original * failures retain identity where attachable, otherwise remain reachable through the error chain. */ run(
    stages: readonly IMiddlewarePipelineStage<TMode, TValue, TSignals>[],
    value: TValue,
    done: IMiddlewarePipelineDone<TMode, TValue>,
    control?: IMiddlewarePipelineControlOptions,
  ): IMiddlewarePipelineRunResult<TMode>;
}>;

export type IMiddlewarePipelineContext = {
  /** * Host-owned effective signal after run-level override; running work must cooperate with * cancellation. */ readonly signal: IAbortSignal;
};

export type IMiddlewarePipelineControlOptions = {
  /** Overrides the construction signal when supplied; undefined falls back to that default. */ readonly signal?: IAbortSignal;
};

export type IMiddlewarePipelineLiftSource<TMode extends IMiddlewarePipelineMode> = {
  readonly sync: 'sync';
  readonly async: 'sync' | 'async';
  readonly generator: 'sync' | 'generator';
  readonly 'async-generator': 'sync' | 'generator' | 'async-generator';
}[TMode];

export type IMiddlewarePipelineStage<
  TMode extends IMiddlewarePipelineMode,
  TValue,
  TSignals extends IGeneratorMiddlewareSignals =
    typeof MiddlewarePipelineGeneratorSignals,
> = {
  readonly sync: ISyncMiddlewareStage<TValue>;
  readonly async: IAsyncMiddlewareStage<TValue>;
  readonly generator: IGeneratorMiddlewareStage<TValue, TSignals>;
  readonly 'async-generator': IAsyncGeneratorMiddlewareStage<TValue, TSignals>;
}[TMode];

export type IMiddlewarePipelineViolationHandler = (
  kind: IMiddlewarePipelineViolation,
) => void;

export type ISyncMiddlewareStage<TValue> = (
  value: TValue,
  next: (value: TValue) => void,
  context?: IMiddlewarePipelineContext,
) => void;

export declare const MiddlewarePipelineErrorCode: {
  /** * Reports failure in both the current stage and its started downstream when no error combiner is * supplied. Also identifies unclassified stage, terminal, host, violation callback, or combiner * failures while preserving native identity where possible and retaining original failures. * Inspect both independent failures in `AggregateError.errors`, or supply an error combiner that * retains them through cause/errors when a domain-specific error is required. */ readonly executionFailed: 'EXECUTION_FAILED';
  /** * Several independent sync traversals or unobserved async traversals failed. Inspect submission * order; each entry is the original failure, independent of its settlement order. */ readonly multipleDownstreamFailed: 'MULTIPLE_DOWNSTREAM_FAILED';
  /** * Invalid mode, onViolation or other callback, signal/control shape, signals, or lift target. The * caller must correct the supplied option rather than retrying the same input. */ readonly invalidOption: 'INVALID_OPTION';
  /** * A cooperative checkpoint observes cancellation. Unclassified Error reasons gain identity where * attachable; other reasons remain on cause. Started work is awaited, not forcibly interrupted. */ readonly aborted: 'ABORTED';
  /** Iterator cleanup failed during cancellation. errors contains abort first, then cleanup failure. */ readonly abortCleanupFailed: 'ABORT_CLEANUP_FAILED';
};

export declare const MiddlewarePipelineGeneratorSignals: Readonly<{
  /** Default explicit-undefined control, identical to GENERATOR_UNDEFINED. */ readonly undefined: typeof GENERATOR_UNDEFINED;
  /** Default halt control, identical to GENERATOR_HALT. */ readonly halt: typeof GENERATOR_HALT;
  /** Default last-yield continuation control, identical to GENERATOR_CONTINUE. */ readonly continue: typeof GENERATOR_CONTINUE;
}>;

export declare const MiddlewarePipelineMode: {
  /** Linear synchronous stages: next only submits a value; downstream runs after the stage returns. */ readonly sync: 'sync';
  /** Awaitable onion stages: the first next starts downstream and returns its promise. */ readonly async: 'async';
  /** Synchronous generators: drain each stage and reduce its final return before continuing. */ readonly generator: 'generator';
  /** Await each generator iteration and terminal callback; run returns a promise. */ readonly asyncGenerator: 'async-generator';
};

