            IPluginHostCore<
              TValue,
              Record<PropertyKey, unknown>,
              import('./plugin-lifecycle-types.ts').IPluginConfig,
              TPipelines
            >,
          TPlugins,
          TInstalled
        >
    ): Promise<IPluginHandleTuple<TPlugins>>;
    /** Observes a dependency-aware removal plan without cleanup or revision change. */ unUse(
      name: string,
      options: IPluginDependencyMutationOptions & Readonly<{ readonly dryRun: true }>,
    ): Promise<IPluginDependencyPlan>;
    /** * Removes or suspends according to policy; cleanup failures return ok:false with affected * changes. */ unUse(
      name: string,
      options?: IPluginDependencyMutationOptions &
        Readonly<{ readonly dryRun?: false }>,
    ): Promise<IPluginRemoval>;
    /** Starts a lazy registration and needed providers; same-name pending callers share one Promise. */ activate(
      name: string,
    ): Promise<IPluginHandle<IPluginConstraint<any>>>;
    /** * Installs a same-name candidate before withdrawing the old generation; failure preserves the * old. */ replace<
      TPlugin extends IPluginConstraint<any>,
    >(
      name: string,
      next: TPlugin,
    ): Promise<IPluginHandle<TPlugin>>;
    /** Adds an unowned sync stage and returns this same handle; incompatible runner modes fail. */ usePipeline(
      stage: ISyncMiddlewareStage<TValue>,
    ): IHostHandle<TDomainCore, TValue, TInstalled, TPublicSurface, TPipelines>;
    /** Adds an unowned async stage, subject to canonical mode lifting and execution guards. */ useAsyncPipeline(
      stage: IAsyncMiddlewareStage<TValue>,
    ): IHostHandle<TDomainCore, TValue, TInstalled, TPublicSurface, TPipelines>;
    /** Adds an unowned generator stage using the middleware generator-return protocol. */ useGeneratorPipeline(
      stage: IGeneratorMiddlewareStage<TValue>,
    ): IHostHandle<TDomainCore, TValue, TInstalled, TPublicSurface, TPipelines>;
    /** Adds an unowned async-generator stage; the Host still owns execution cancellation/leases. */ useAsyncGeneratorPipeline(
      stage: IAsyncGeneratorMiddlewareStage<TValue>,
    ): IHostHandle<TDomainCore, TValue, TInstalled, TPublicSurface, TPipelines>;
    /** * Runs the current stage snapshot; done receives the final delivered value if traversal reaches * it. */ runPipeline(
      value: TValue,
      done: (value: TValue) => void,
    ): void | Promise<void>;
    /** Runs synchronous stages, rejecting before effects if any visible async stage exists. */ runPipelineSync<
      TResult,
    >(
      value: TValue,
      done: (value: TValue) => TResult,
    ): TResult | undefined;
    /** Waits for async execution; an empty lane returns the exact terminal Promise. */ runPipelineAsync<
      TResult,
    >(
      value: TValue,
      done: (value: TValue) => Promise<TResult>,
    ): Promise<TResult | undefined>;
    /** Shared singleflight completion; defaults to structured cleanup, custom middleware may reject. */ dispose(): Promise<IPluginHostDisposalResult>;
  }> &
    IPluginHostRuntimeExtensions<TInstalled> &
    IPluginHostCoreTypeInfo<TDomainCore, TValue, TPipelines>,
  Extract<keyof TPublicSurface, 'use' | 'unUse'>
> &
  Readonly<TPublicSurface>;

export type IPipelineConfig = {
  /** Defaults to sync; accepts sync, async, generator or async-generator. */ mode?: IMiddlewarePipelineMode;
};

export type IPipelineDefinitions = Readonly<
  Record<string, IPipelineSpec<any, IMiddlewarePipelineMode>>
>;

export type IPipelineMode<TSpec> = TSpec extends {
  readonly mode: infer TMode extends IMiddlewarePipelineMode;
}
  ? TMode
  : TSpec extends IPipelineSpec<any, infer TMode>
    ? TMode
    : 'sync';

export type IPipelineOwner<TSpec> = Pick<IPipelineRegistration<TSpec>, 'use'> &
  Readonly<{
    /** Delivers terminal values and returns the result appropriate to this pipeline's mode. */ run<
      TResult,
    >(
      value: IPipelinePayload<TSpec>,
      done: (value: IPipelinePayload<TSpec>) => TResult,
    ): IPipelineRunResult<TSpec, TResult>;
  }>;

export type IPipelineRegistration<
  TSpec,
  TVisible extends IPipelineDefinitions = Record<never, never>,
> = Readonly<{
  /** Registers one stage owned by this exact install generation. */ use(
    stage: IPipelineStage<TSpec>,
  ): IPipelineStageHandle;
  /** Splices a visible pipeline at this occurrence using the same native stage lifetime. */ through<
    TName extends IPipelineThroughName<TSpec, TVisible>,
  >(
    name: TName,
  ): IPipelineStageHandle;
}>;

export type IPipelineRunResult<TSpec, TResult> =
  IPipelineMode<TSpec> extends 'sync' | 'generator'
    ? TResult | undefined
    : Promise<Awaited<TResult> | undefined>;

export type IPipelineScope<TVisible extends IPipelineDefinitions> = Readonly<{
  /** Resolves only declared host, own short and dependency-qualified names. */ pipeline<
    TName extends keyof TVisible & string,
  >(
    name: TName,
  ): IPipelineRegistration<TVisible[TName], TVisible>;
}>;

export type IPipelineSpec<
  TPayload = unknown,
  TMode extends IMiddlewarePipelineMode = IMiddlewarePipelineMode,
> = Readonly<
  Omit<IPipelineSpecOptions, 'mode'> & {
    /** Selected runner mode; absent configuration means sync. */ mode?: TMode;
    /** Type-only marker used to infer the payload without a parallel type table. */ readonly [pipelinePayload]?: TPayload;
  }
>;

export type IPipelineSpecOptions = Readonly<{
  /** Omission selects the synchronous runner. */ mode?: IMiddlewarePipelineMode;
  /** Omission preserves single-submission middleware semantics. */ next?: MiddlewarePipelineNext;
  /** Stage allocation order is used unless reverse is explicitly requested. */ order?: PipelineOrder;
}>;

export type IPipelineStage<TSpec> =
  IPipelineMode<TSpec> extends 'async'
    ? IAsyncMiddlewareStage<IPipelinePayload<TSpec>, unknown>
    : IMiddlewarePipelineStage<IPipelineMode<TSpec>, IPipelinePayload<TSpec>>;

export type IPipelineStageHandle = Readonly<{
  /** Removes this occurrence once; repeated calls have no effect. */ remove(): void;
}>;

export type IPluginAdmission<TPlugin extends IPluginConstraint<any>> = Readonly<{
  readonly [pluginAdmissionBrand]?: TPlugin;
}>;

export type IPluginAdmissionRequest = Readonly<{
  /** Opaque definition snapshot produced by the canonical admission factory. */ readonly admission: IPluginAdmission<
    IPluginConstraint<any>
  >;
  /** Live ordering lane issued by the receiving Host for this same definition name. */ readonly slot: IPluginDataOrderSlot;
}>;

export type IPluginBatchRemovalLeaf = ICleanupResult &
  Readonly<{
    /** Exact registration generation revoked by this leaf. */ readonly receipt: IRegistrationToken;
    /** Registration name retained for correlating cleanup observations. */ readonly name: string;
    /** True only when this leaf has no cleanup errors or unsettled physical continuation. */ readonly cleanupComplete: boolean;
  }>;

export type IPluginBatchRemovalOptions = Readonly<{
  /** * Optional external lease fence; logical revocation precedes waiting, physical cleanup follows * it. */ readonly beforeCleanup?: PromiseLike<void>;
}>;

export type IPluginBatchRemovalResult<TSnapshot> = ICleanupResult &
  Readonly<{
    /** True when the committed batch has no cleanup errors or physical continuation. */ readonly ok: boolean;
    /** Logical removal already committed even if cleanup is incomplete or failed. */ readonly committed: true;
    /** Remaining Host publication captured immediately after logical revocation. */ readonly snapshot: TSnapshot;
    /** Per-registration cleanup observations in dependency-safe cleanup order. */ readonly leaves: readonly IPluginBatchRemovalLeaf[];
    /** True only when the batch reports no cleanup errors or unsettled continuation. */ readonly cleanupComplete: boolean;
  }>;

export type IPluginBeforeReleaseContext = Readonly<
  IPluginDisposalContext & {
    /** Nonnegative budget remaining on the Host clock, or undefined for unbounded release. */ remainingMs():
      | number
      | undefined;
  }
>;

export type IPluginConstraint<
  TCore,
  TFeatures extends IFeatureRecord = Record<never, never>,
  TExpose extends object = Record<never, never>,
> = {
  /** Nonempty dot-free registration name used for routing and configuration paths. */ readonly name: string;
  /** Configuration input captured by canonical admission; omission means an empty config. */ readonly config?: unknown;
  /** Optional trusted Feature roots retained with their definition identities. */ readonly features?: TFeatures;
  /** Eager by default; lazy defers setup, Features and install until activation. */ readonly activation?:
    | 'eager'
    | 'lazy';
  /** Async-capable config validation hook; failed updates never commit their patch. */ update?: (
    next: never,
    core: TCore &
      IPluginLifecycleCore<any> &
      Readonly<{ features: IFeatureOutputs<TFeatures>; featureExpose: TExpose }>,
  ) => IPluginAwaitable<void>;
  /** Notification after installation or reenablement; its failure is diagnostic, not rollback. */ onEnable?: (
    context: IPluginRegistrationContext,
  ) => IPluginAwaitable<void>;
  /** Notification after disabling; it does not own or release registration resources. */ onDisable?: (
    context: IPluginRegistrationContext,
  ) => IPluginAwaitable<void>;
  /** Optional provider rebind hook; absent or failed hooks select dependent restart. */ onDependencyReplaced?: (
    name: string,
    outputs: Readonly<Record<string, object>>,
  ) => IPluginAwaitable<void>;
  /** Physical plugin cleanup before resources; errors are retained while remaining cleanup proceeds. */ dispose?: (
    context?: IPluginDisposalContext,
  ) => IPluginAwaitable<void>;
  /** Captured before the registration enters its bounded release step. */ beforeRelease?: (
    context: IPluginBeforeReleaseContext,
  ) => IPluginAwaitable<void>;
  /** Captured async fallback when no explicit dispose hook exists. */ [asyncDisposeKey]?: () => IPluginAwaitable<void>;
  /** Captured sync fallback after the explicit and async disposer choices. */ [Symbol.dispose]?: () => void;
} & (
  | IPluginPlainHooks<TCore, Record<string, unknown>, any, TFeatures, TExpose>
  | {
      /** Declared setup requires the asynchronous installation path unless registration stays lazy. */ readonly setup: (
        context: IPluginSetupContext<any>,
      ) => unknown;
      /** Expose input optionally derives from the exact setup output. */ readonly featureExpose?:
        | TExpose
        | ((core: TCore & IPluginLifecycleCore<any>, setupOutput?: any) => TExpose);
      /** Install runs only after successful setup and Feature construction. */ install: (
        core: IPluginHookCore<TCore, any, TFeatures, TExpose>,
        setupOutput?: any,
      ) => IPluginAwaitable<Record<string, unknown>>;
    }
);

export type IPluginConstraintTuple<
  TCore,
  TPlugins extends readonly IPluginConstraint<any>[],
  TInstalled extends readonly IPluginConstraint<any>[] = readonly [],
> = {
  readonly [K in keyof TPlugins]: [TPlugins[K]] extends [never]
    ? IPluginConstraint<TCore>
    : IPluginConstraint<
        TCore,
        IPluginConstraintFeatures<TPlugins[K]>,
        IPluginConstraintExpose<TPlugins[K]>
      > &
        IPluginRuntimeConstraint<readonly [...TInstalled, ...TPlugins], TPlugins[K]> &
        (TPlugins[K] extends {
          readonly [definedPluginBrand]: { readonly core: infer TRequired };
        }
          ? TRequired extends Record<string, never>
            ? unknown
            : TCore extends TRequired
              ? unknown
              : never
          : unknown);
};

export type IPluginDataOrderSlot = Readonly<{
  readonly __pluginDataOrderSlot: unique symbol;
}>;

export type IPluginDependency = Readonly<{
  /** Name of one cross-plugin provider found in the selected local Feature closure. */ readonly provider: string;
  /** True if any reference to this provider is required; required wins over optional duplicates. */ readonly required: boolean;
}>;

export type IPluginDependencyMutationOptions = Readonly<{
  /** * Defaults to reject; cascade removes/disables required dependents, suspend retains them * inactive. */ readonly policy?: import('@migaia/capability/graph/dependency').DependencyPolicy;
  /** Defaults to false; true returns a plan without revocation, cleanup or revision change. */ readonly dryRun?: boolean;
}>;

export type IPluginDependencyPlan = Readonly<{
  /** Admitted reject, cascade or suspend policy used to construct this plan. */ readonly policy: import('@migaia/capability/graph/dependency').DependencyPolicy;
  /** Dependency-safe action order projected to registration names. */ readonly order: readonly string[];
  /** Explicit planned actions; an actual removal's affected result includes only applied changes. */ readonly steps: readonly IPluginDependencyPlanStep[];
  /** Provider-to-consumer edges relevant to the mutation, including absent optional providers. */ readonly edges: readonly Readonly<{
    /** Name of the supplying plugin. */ readonly provider: string;
    /** Name of the plugin that declares this dependency. */ readonly consumer: string;
    /** Whether the declared reference tolerates an absent provider. */ readonly optional: boolean;
    /** Present only to identify an optional edge whose provider is absent. */ readonly status?: 'optional-absent';
  }>[];
