export type IPluginDisableToken<
  _THost,
  TPlugin extends IPluginConstraint<any>,
  _TInstalled extends readonly IPluginConstraint<any>[],
  _TDomainCore extends object,
  _TValue,
> = Readonly<{
  /** Name retained by this exact registration's restore token. */ readonly name: TPlugin['name'];
  /** Reenables the captured registration; replacement/removal cannot be restored by a stale token. */ enable(): Promise<void>;
}>;

export type IPluginDisposalContext = Readonly<{
  /** Registration lifetime signal, which may already be aborted when physical cleanup runs. */ readonly signal: INativeAbortSignal;
  /** Shared cleanup deadline when one was selected, otherwise undefined. */ readonly deadlineAt:
    | number
    | undefined;
}>;

export type IPluginEnablement<
  THost,
  TInstalled extends readonly IPluginConstraint<any>[],
  TDomainCore extends object,
  TValue,
> = Readonly<{
  /** Plans dependency-aware disablement without changing availability when dryRun is true. */ disable(
    name: string,
    options: IPluginDependencyMutationOptions & Readonly<{ readonly dryRun: true }>,
  ): Promise<IPluginDependencyPlan>;
  /** Disables access while retaining resources, returning a token for this exact registration. */ disable(
    name: string,
    options?: IPluginDependencyMutationOptions & Readonly<{ readonly dryRun?: false }>,
  ): Promise<
    Readonly<{
      /** Restores the exact changed disable set in dependency-safe order, not a later generation. */ readonly token: IPluginDisableToken<
        THost,
        any,
        TInstalled,
        TDomainCore,
        TValue
      >;
    }>
  >;
  /** Reenables a name and resumes eligible required dependents; registration resources are retained. */ enable(
    name: string,
  ): Promise<void>;
  /** Frozen snapshot of explicitly disabled names; suspended dependents are a distinct state. */ disabled(): readonly string[];
}>;

export type IPluginFeatureCore<
  TFeatures extends IFeatureRecord,
  TExpose extends object & IFeatureRecordRequiredExpose<TFeatures>,
