  /** Registration-owned guarded method facade available to Feature factories. */ readonly featureExpose: TExpose;
}>;

export type IPluginFeatureOptions<
  TCore extends object,
  TConfig extends IPluginConfig,
  TFeatures extends IFeatureRecord,
  TExpose extends object & IFeatureRecordRequiredExpose<TFeatures>,
> = Readonly<{
  /** Optional trusted roots; omitted means no selected Features. */ readonly features?: TFeatures;
  /** Explicit expose methods or a synchronous factory; omitted means an empty method surface. */ readonly featureExpose?:
    | TExpose
    | ((core: TCore & IPluginLifecycleCore<TConfig>) => TExpose);
}>;

export type IPluginHandle<TPlugin extends IPluginConstraint<any>> = Readonly<{
  /** Stable name; other members resolve the current registration with this name on every read. */ readonly name: TPlugin['name'];
  /** Frozen facade for the current generation; retained callable members reject after revocation. */ readonly extensions: Readonly<
    IExtractPluginExt<TPlugin>
  >;
  /** * Reads a declared ready Feature; missing, disabled, suspended or cold registrations fail * explicitly. */ getFeature<
    TKey extends IPluginFeatureName<TPlugin>,
  >(
    name: TKey,
  ): IPluginFeatureOutput<TPlugin, TKey>;
  /** Name-scoped config reader/updater, subject to the same registration availability checks. */ readonly config: IPluginHandleConfig<TPlugin>;
}>;

export type IPluginHandleConfig<TPlugin> = Readonly<{
  /** Current name-addressed owned snapshot; access checks Host and registration availability. */ get(): IReadonlyConfig<
    IExtractPluginConfig<TPlugin>
  >;
  /** Queued synchronous recipe returning a shallow patch; hook success is required before commit. */ update(
    recipe: (
      previous: IReadonlyConfig<IExtractPluginConfig<TPlugin>>,
    ) => Partial<IExtractPluginConfig<TPlugin>>,
  ): Promise<void>;
}>;

export type IPluginHandleTuple<TPlugins extends readonly IPluginConstraint<any>[]> = {
  readonly [K in keyof TPlugins]: TPlugins[K] extends IPluginConstraint<any>
    ? IPluginHandle<TPlugins[K]>
    : never;
};

export type IPluginHostConfigFor<TPlugins extends readonly unknown[]> = {
  /** Reads an owned snapshot/path, returning undefined for an absent plugin or child path. */ get(
    path: string,
  ): unknown | undefined;
  /** Typed name overload; the recipe sees latest committed config and returns a synchronous patch. */ update<
    TName extends Extract<TPlugins[number], { readonly name: string }>['name'],
  >(
    name: TName,
    recipe: (
      previous: IReadonlyConfig<IExtractPluginConfig<IPluginByName<TPlugins, TName>>>,
    ) => Partial<IExtractPluginConfig<IPluginByName<TPlugins, TName>>>,
  ): Promise<void>;
  /** Dynamic-name overload with the same transactional commit and callback-failure semantics. */ update(
    name: string,
    recipe: (previous: IReadonlyConfig<IPluginConfig>) => Partial<IPluginConfig>,
  ): Promise<void>;
};

export interface IPluginHostCore<
  TValue = never,
  _TLegacyShared extends object = Record<PropertyKey, unknown>,
  TConfig extends IPluginConfig = IPluginConfig,
  TPipelines extends IPipelineDefinitions = Record<never, never>,
> {
  /** Registration-only authority for a name declared by this Host. */ pipeline<
    TName extends keyof TPipelines & string,
  >(
    name: TName,
  ): IPipelineRegistration<TPipelines[TName], TPipelines>;
  /** Reads this registration's current immutable config; no mutation capability is exposed here. */ readonly config: IPluginLifecycleConfig<TConfig>;
  /** Current operation signal/deadline, separate from the registration lifetime. */ readonly operation: IPluginOperationContext;
  /** Registration lifetime signal, revoked when this generation is logically removed. */ readonly lifecycle: IPluginRegistrationContext;
  /** Owns a resource during install only; late calls reject without taking ownership of the input. */ onDispose(
    resource: IPluginResource,
  ): void;
  /** Adds an install-owned sync stage, lifted only when compatible with the Host runner. */ usePipeline(
    stage: ISyncMiddlewareStage<TValue>,
  ): this;
  /** * Adds an install-owned async stage; unsupported runner combinations throw * PIPELINE_MODE_MISMATCH. */ useAsyncPipeline(
    stage: IAsyncMiddlewareStage<TValue>,
  ): this;
  /** Adds an install-owned generator stage under the canonical middleware signal protocol. */ useGeneratorPipeline(
    stage: IGeneratorMiddlewareStage<TValue>,
  ): this;
  /** Adds an install-owned async-generator stage; later revocation removes it from new runs. */ useAsyncGeneratorPipeline(
    stage: IAsyncGeneratorMiddlewareStage<TValue>,
  ): this;
}

examples:
import {
  defineHost,
  definePlugin,
  pipelineSpec,
  type IPluginHostCoreFor
} from '@migaia/plugin-host'

const pipelines = {
  count: pipelineSpec<number>()({ mode: 'sync' }),
  text: pipelineSpec<{ text: string }>()({ mode: 'async', next: 'multiple', order: 'reverse' })
}
const host = defineHost({
  host: { execution: { mutationTimeoutMs: 5000, pipelineDrainTimeoutMs: 5000 } },
  pipelines
})
const format = definePlugin({
  name: 'format',
  install(core: IPluginHostCoreFor<typeof host>) {
    core.pipeline('count').use((value, next) => next(value + 1))
    core.pipeline('text').use(async (value, next) => {
      await next({ text: value.text.toUpperCase() })
      await next({ text: value.text.toLowerCase() })
    })
    return {}
  }
})
await host.use(format)
const count = host.pipeline('count').run(1, (value) => value)
const texts: string[] = []
await host.pipeline('text').run({ text: 'Hi' }, (value) => {
  texts.push(value.text)
})
console.log(count, texts.join(','))
await host.unUse('format')
console.log(host.pipeline('count').run(1, (value) => value))
await host.dispose()

