  ): void;
  /** Reuse original Host/registration admission for explicitly exposed reserved controls. */ assertCurrent(): void;
  /** * Admit this exact prepared registration while its original batch has a current install, or reuse * ordinary published admission. This grants no install, resource, or mutation authority. */ assertPreparedRegistration(): void;
  /** Read an already committed facade without acquiring ownership or creating another slot. */ readSharedExtension(
    key: PropertyKey,
  ): object | undefined;
  /** * Acquires one canonical key/family slot during this core's original uncommitted install only. * Conflicting keys/families fail admission; later calls cannot create a parallel publication. */ acquireSharedSlot<
    TFacade extends object,
  >(
    key: PropertyKey,
    family: object,
    create: (slot: IPluginRuntimeSharedSlot<TFacade>) => TFacade,
  ): IPluginRuntimeSharedSlot<TFacade>;
  /** Capture the cold inventory once; availability remains a per-call Host decision. */ readFeatureOutputs(
    name: string,
  ): IPluginRuntimeFeatureSnapshot;
}>;

export type IPluginRuntimeSharedSlot<TFacade extends object = object> = Readonly<{
  /** One stable facade for this Host key/family, created by its canonical extension owner. */ readonly facade: TFacade;
  /** An absent target returns undefined; duplicated instance identity returns null. */ find(
    target: string,
  ): object | null | undefined;
  /** Snapshot of current ready contributions, separate from cold registration inventory. */ values(): readonly object[];
  /** * Cold inventory reads every committed reservation, including registrations without ready * sessions. */ registered(): readonly object[];
  /** Annotates this exact original reservation; metadata is published only with its install commit. */ register(
    value: object,
    onCommit?: () => void,
  ): void;
  /** Withdraw only this exact ready contribution; the live registration retains its shared slot. */ contribute(
    value: object,
    instanceId: string,
  ): () => void;
}>;

export type IPluginSetup<TConfig extends IPluginConfig, TSetup> = (
  context: IPluginSetupContext<TConfig>,
) => TSetup | PromiseLike<TSetup>;

export type IPluginSetupContext<TConfig extends IPluginConfig = IPluginConfig> =
  Readonly<{
    /** Read-only configuration for this registration's setup attempt. */ readonly config: IPluginLifecycleConfig<TConfig>;
    /** Setup-owned signal, deadline and clock, independent of subsequent mutations. */ readonly operation: IPluginSetupOperation;
    /** Registration lifetime signal retained after successful setup. */ readonly lifecycle: IPluginRegistrationContext;
    /** Owns a setup resource; late registration releases it before reporting RESOURCE_OUTSIDE_INSTALL. */ onDispose(
      resource: IPluginResource,
    ): void;
  }>;

export type IPluginSetupOperation = Readonly<{
  /** Setup-attempt cancellation; late settlement cannot regain publication authority. */ readonly signal: INativeAbortSignal;
  /** Absolute deadline in the Host scheduler clock, or undefined without a mutation timeout. */ readonly deadlineAt:
    | number
    | undefined;
  /** Reads the Host scheduler clock used for the deadline. */ now(): number;
}>;

export declare const isDefinedPlugin: (
  value: unknown,
) => value is IDefinedPluginConstraint;

export declare const pipelineSpec: <TPayload>() => <
  const TConfig extends IPipelineSpecOptions,
>(
  config: TConfig,
) => IPipelineSpec<
  TPayload,
  TConfig extends { readonly mode: infer TMode extends IMiddlewarePipelineMode }
    ? TMode
    : 'sync'
> &
  TConfig;

