export declare class PluginHost<
  TDomainCore extends object,
  TValue = never,
  TInstalled extends
    readonly import('./plugin-definition-types.ts').IPluginConstraint<any>[] =
    readonly [],
  TPipelines extends IPipelineDefinitions = Record<never, never>,
> extends RuntimeHost<TDomainCore, TValue, TInstalled, TPipelines> {
  /** * Creates an empty Host. options.execution budgets default to 5000 ms each and may be overridden. * Invalid budgets/options fail before plugin hooks run; no plugin is installed by construction. * Own the resulting Host until its shared dispose() completion has been observed. */ constructor(
    options?: import('./host-options-types.ts').IPluginHostOptions<TPipelines>,
  );
}

export declare const PluginHostDisposalNodeKind: Readonly<{
  /** Semantic error node created by the Host cleanup producer. */ readonly hostError: 'host-error';
  /** Aggregate node retaining several original cleanup failures in order. */ readonly aggregate: 'aggregate';
  /** Phase wrapper whose cause preserves a disposer failure. */ readonly disposerWrapper: 'disposer-wrapper';
}>;

export declare class PluginHostError<TDetail = IPluginHostErrorDetail> extends Error {
  /** The `source` component of `(source, code)`, always `'plugin.host'`. */ readonly source: string;
  /** Stable scenario code from PluginHostErrorCode, independent of the human-readable message. */ readonly code: IPluginHostErrorCode;
  /** * Structured diagnostics, such as queue timeout `owner` and `waitedMs`, kept separate from * `cause`. */ readonly detail?: TDetail;
  /** Constructs a semantic error without rewriting the original error carried by options.cause. */ constructor(
    code: IPluginHostErrorCode,
    message: string,
    options?: ErrorOptions & {
      /** Optional producer-owned diagnostic payload, retained by identity rather than copied. */ readonly detail?: TDetail;
    },
  );
}

export declare const PluginHostErrorCode: {
  /** * Thrown when a mutation or registration targets a host after disposal completes. * * The terminal state is irreversible. Create a new host instead of reviving this one. Enforces * the terminal boundary of the two-phase lifecycle contract. */ readonly hostDisposed: 'HOST_DISPOSED';
  /** * Thrown when a mutation targets a closing host after `dispose()` starts but before the terminal * state. * * This differs from `HOST_DISPOSED` so diagnostics distinguish disposal in progress from * completed disposal. Retrying later cannot reopen either host. */ readonly hostDisposing: 'HOST_DISPOSING';
  /** * Thrown when installing a plugin whose `name` is already occupied. * * Plugin names are unique host keys. Rename the plugin or `unUse()` the previous plugin first. */ readonly pluginDuplicate: 'PLUGIN_DUPLICATE';
  /** * Thrown when `unUse()` or another operation targets an uninstalled plugin name. * * Check for repeated removal or a misspelled name. Host state stays unchanged. Prepared removals * also reject this code when their exact generation is no longer current; no cleanup may repeat * and a replacement registration stays live. */ readonly pluginNotInstalled: 'PLUGIN_NOT_INSTALLED';
  /** * A handle member, or an extension taken from it, is used while that plugin is disabled; also * thrown by `activate()` on a disabled lazy plugin. Enforces per-registration liveness; the * caller should `enable` the plugin (or its restore token) before retrying. */ readonly pluginDisabled: 'PLUGIN_DISABLED';
  /** * A dependent plugin is temporarily suspended because one of its required providers is inactive. * The caller must restore or reinstall the provider and wait for automatic resume before * retrying. Enforces the suspend dependency policy without treating the registration as removed. */ readonly pluginSuspended: 'PLUGIN_SUSPENDED';
  /** * A lazy plugin is accessed synchronously before activation, or a synchronous install needs an * inactive lazy provider. Activation is an explicit async step; the caller should `await * host.activate(name)` or install through the async `use()` path. */ readonly pluginNotActivated: 'PLUGIN_NOT_ACTIVATED';
  /** * `definition.getFeature(name)` or `handle.getFeature(name)` named a Feature the plugin does not * declare. Lookups never return `undefined`; the caller has a wrong name or wrong plugin. */ readonly featureNotDeclared: 'FEATURE_NOT_DECLARED';
  /** * A required Feature provider was never installed in this host (a removed one reports * `PREREQUISITE_REMOVED`). Thrown before any install hook runs; install the provider first or in * the same batch. */ readonly prerequisiteMissing: 'PREREQUISITE_MISSING';
  /** * Cross-plugin Feature references inside one batch form a cycle. Detected before any install hook * runs; the caller must break the cycle in its plugin definitions. */ readonly dependencyCycle: 'DEPENDENCY_CYCLE';
  /** * `unUse`/`disable` (or a managed removal) would leave required dependents behind and cascade was * not requested. State is unchanged; `detail.blockedBy` lists every transitive dependent in * cascade order — pass `policy: 'cascade'`, include them, or inspect `dryRun` first. */ readonly dependencyBlocked: 'DEPENDENCY_BLOCKED';
  /** * `replace(name, next)` received a candidate whose name differs from `name`. Nothing is * installed; the caller passed the wrong definition. */ readonly replaceNameMismatch: 'REPLACE_NAME_MISMATCH';
  /** * `replace()` published the new provider, but at least one dependent that had to restart (no * `onDependencyReplaced`, or the hook threw) failed to reinstall. The replacement stays * committed, the previous provider is disposed, and the failed restart closure stays uninstalled. * `cause` is an `AggregateError` whose first entry is the restart failure, followed by the hook * and cleanup errors; the caller should reinstall the listed dependents after fixing them. */ readonly dependentRestartFailed: 'DEPENDENT_RESTART_FAILED';
  /** * A plugin definition carries a retired or unsupported field (for example `shared`), or its * dependency data is structurally invalid, or runtime integration is requested from an object * that is not a canonical module-minted core. Definition admission and the runtime integration * port reject these inputs; migrate to Feature dependencies or use the original install core. */ readonly pluginDefinitionInvalid: 'PLUGIN_DEFINITION_INVALID';
  /** * Thrown when plugin installation or publication fails. Native shared-publication TypeErrors * retain their runtime type with this code. The original installation error always remains * primary and is reachable by identity through `cause`, as required by the error-code contract. * * `detail` retains the failed plugin name and original rollback failures in rollback order. Async * `use()` publishes the completed frozen detail directly. Sync `useSync()` publishes a frozen * snapshot and exposes the final frozen detail through `detail.completion`. Rollback or cleanup * failures use the diagnostic code `PLUGIN_INSTALL_ROLLBACK_FAILED`. They never replace the * original construction failure. Await completion before converting errors that require complete * secondary failure identities. */ readonly pluginInstallFailed: 'PLUGIN_INSTALL_FAILED';
  /** * A plugin selected for immediate `useSync()` installation declares async setup. * * Callers must install it through `use()` so setup settles before features and install run. */ readonly setupRequiresAsyncInstall: 'SETUP_REQUIRES_ASYNC_INSTALL';
  /** * Thrown when a cleanup step fails during one plugin's `unUse()` or `beforeRelease()`. * * Failures are aggregated after unloading finishes. One disposer failure does not stop remaining * releases. Treat this as a resource-leak warning, not a signal that host state rolls back. */ readonly pluginDisposeFailed: 'PLUGIN_DISPOSE_FAILED';
  /** * Thrown when an extension returned by `install()` conflicts with an existing host property. A * shared slot accepts only canonical contributions from registrations in the same family. * Ordinary extensions and other families cannot occupy the same key. * * Ordinary extension properties remain exclusive. Rename the property or use a canonical * same-family contribution. Conflict detection happens before mounting, so no partially mounted * state is published. */ readonly extensionDuplicate: 'EXTENSION_DUPLICATE';
  /** * Thrown when an extension name conflicts with an `Object.prototype` key such as `toString` or * `constructor`. * * Rejecting it before mounting preserves prototype lookup and prevents a prototype-pollution * entry point. */ readonly extensionObjectPrototype: 'EXTENSION_OBJECT_PROTOTYPE';
  /** * Thrown when an extension uses a reserved host key such as `config`, `onDispose`, or * `usePipeline`. * * Reserved keys belong to the host protocol. Overwriting them would let plugins disrupt each * other. Choose another extension name. */ readonly extensionReserved: 'EXTENSION_RESERVED';
  /** * A Feature prerequisite exists but its owner is temporarily disabled. The caller may enable that * owner and retry the same lookup. */ readonly prerequisiteDisabled: 'PREREQUISITE_DISABLED';
  /** * A previously published Feature prerequisite lost its owner through removal. The caller must * install a provider again; retrying the unchanged lookup cannot recover it. */ readonly prerequisiteRemoved: 'PREREQUISITE_REMOVED';
  /** * Thrown when a plugin context registers an `onDispose()` resource outside installation or after * setup ends. Resources belong to the current attempt. A late setup-context registration releases * its resource before rejecting; core.onDispose() outside install rejects without acquiring that * input. Register through the context that owns the active setup or installation phase. */ readonly resourceOutsideInstall: 'RESOURCE_OUTSIDE_INSTALL';
  /** * Thrown when a plugin lifecycle callback (`setup`, `install`, `dispose`, `update`, or * `beforeRelease`) reenters a host mutation API, or an external `config.update()` runs during * setup or `beforeRelease`. A synchronous `activate()` reentry rejects before sharing an existing * activation. After an await, same-name activation callers share that Promise regardless of * origin; callers must avoid awaiting their own activation. * * Reentrancy makes installation rollback boundaries ambiguous. Move later mutations outside * lifecycle callbacks. Also rejects explicit removal/replacement while the exact registration's * domain admission predicate forbids revocation; close the domain's live work and retry. Full * Host disposal and failed-install rollback remain unconditional cleanup. */ readonly lifecycleMutation: 'LIFECYCLE_MUTATION';
  /** * Thrown during host construction for a pipeline mode outside `sync`, `async`, `generator`, or * `async-generator`. * * Configuration validation rejects the input before the host is constructed. */ readonly invalidPipelineMode: 'INVALID_PIPELINE_MODE';
  /** Construction rejected an invalid named map, spec, name or order; correct the declaration. */ readonly invalidPipelineOption: 'INVALID_PIPELINE_OPTION';
  /** Lookup named no declared pipeline; declare the name at construction instead of adding it later. */ readonly pipelineUnknown: 'PIPELINE_UNKNOWN';
  /** * Thrown when a registered stage is incompatible with the host's pipeline mode. * * For example, a sync host cannot accept a generator stage. Supported lifting follows the * canonical middleware runner; other combinations fail with both host and stage modes in the * message. Explicit sync/async entries also reject generator hosts; use runPipeline for their * existing generator protocol. Select a compatible runner rather than bypassing stages. */ readonly pipelineModeMismatch: 'PIPELINE_MODE_MISMATCH';
  /** * The synchronous entry sees an installed asynchronous stage. No stage or terminal runs; use * runPipelineAsync or remove/disable that stage before retrying synchronously. */ readonly asyncStageInSyncEntry: 'ASYNC_STAGE_IN_SYNC_ENTRY';
  /** * Thrown when `next()` is called twice within one pipeline step. * * A step can advance only once. Repeated calls would process the same value downstream more than * once. Check stage branches for a missing `return`. */ readonly pipelineNextDuplicate: 'PIPELINE_NEXT_DUPLICATE';
  /** * Reports a `next()` call after the stage returns or completes. * * The value can no longer enter the pipeline safely, so the call is ignored. An async branch that * is not awaited is a common cause. */ readonly pipelineNextLate: 'PIPELINE_NEXT_LATE';
  /** * Thrown when a stage is registered while the pipeline is executing. * * Changing stages during execution would make behavior depend on registration timing. Complete * stage registration before execution starts. */ readonly pipelineExecuting: 'PIPELINE_EXECUTING';
  /** * Thrown when an async stage and its downstream both fail. An `AggregateError` retains `errors` * in the fixed order `[stageError, downstreamError]`. * * Both original errors remain reachable by identity in `errors`. Handle each failure rather than * retrying it as one stage failure. */ readonly pipelineFailed: 'PIPELINE_FAILED';
  /** * Diagnostic code that is reported, never thrown. * * Reports through `diagnostic` when `install()` fails and rollback also fails. The primary error * retains `PLUGIN_INSTALL_FAILED` and `cause` equal to the original installation error. This * additional signal never rewrites or replaces the primary error. Some installed plugins may * remain incompletely unloaded, leaving inconsistent host state. Treat the failure as * unrecoverable and rebuild the host. */ readonly pluginInstallRollbackFailed: 'PLUGIN_INSTALL_ROLLBACK_FAILED';
  /** * Diagnostic code that is reported, never thrown. * * Reports a non-enumerable property intentionally skipped when mounting an `install()` result. * Ignoring such keys is part of the contract, but reporting explains why they are absent from the * host. Make the property enumerable to expose it. */ readonly extensionNonEnumerableIgnored: 'EXTENSION_NON_ENUMERABLE_IGNORED';
  /** * Thrown when a mutation exceeds its configured FIFO admission wait and is removed and rejected. * * The caller configures this admission limit. Without a limit, the host reports waits without * rejecting them. This code wraps lifecycle `QUEUE_ADMISSION_TIMEOUT` at the plugin-host * boundary. `cause` retains the original lifecycle error. * * The mutation is terminated and never executes. This differs from `DISPOSE_STEP_TIMEOUT`, which * stops waiting and continues disposal. */ readonly mutationQueueTimeout: 'MUTATION_QUEUE_TIMEOUT';
  /** * Reported when one disposer exceeds its wait limit without settling. This includes pipeline * disposers, plugin `dispose` or `beforeRelease` hooks, and resource disposers. * * A disposer that awaits the `host.dispose()` call responsible for running it cannot settle on * its own. * * Disposal continues after recording the step as failed and ending the wait. The running disposer * is not cancelled because JavaScript cannot safely revoke an active Promise chain. The * transaction can still reach disposed state. This differs from `MUTATION_QUEUE_TIMEOUT`, which * terminates the queued mutation. */ readonly disposeStepTimeout: 'DISPOSE_STEP_TIMEOUT';
  /** * Thrown as a native `TypeError` with an attached code when input violates its contract. Inputs * include plugin names, configuration paths, stages, extensions, domain cores, and resource * disposers. * * Correct the input before retrying. This is a programming error, not a runtime state failure. */ readonly invalidOption: 'INVALID_OPTION';
  /** Config value violates the admitted plain-data grammar; caller must supply an allowed value. */ readonly invalidConfigValue: 'INVALID_CONFIG_VALUE';
  /** * A public configuration recipe/update, domain-surface descriptor read, or factory disposal * callback failed without a semantic identity. Native mutable errors keep their instance, type, * and stack; immutable/non-Error values stay on cause. Existing upstream source/code stays owned * there. Inspect the callback failure; a rejected configuration patch was not committed and a * disposal completion remains terminal. */ readonly callbackFailed: 'CALLBACK_FAILED';
  /** Config input contains a reference cycle; caller must supply an acyclic value graph. */ readonly configCycleRejected: 'CONFIG_CYCLE_REJECTED';
  /** A lifecycle hook exceeded the admitted mutation budget and lost commit authority. */ readonly mutationExecutionTimeout: 'MUTATION_EXECUTION_TIMEOUT';
  /** A previously published view was logically revoked by removal or disposal. */ readonly registrationRevoked: 'REGISTRATION_REVOKED';
  /** Plugin install returned an own `then` key, which is never a publishable extension result. */ readonly installResultThenable: 'INSTALL_RESULT_THENABLE';
  /** * Active pipeline work exceeded the admitted drain budget; ordinary unUse reports it and returns * ok:false while bounded cleanup continues. */ readonly pipelineDrainTimeout: 'PIPELINE_DRAIN_TIMEOUT';
  /** Logical disposal completed while one or more physical cleanup tasks remain unsettled. */ readonly cleanupIncomplete: 'CLEANUP_INCOMPLETE';
  /** * `openComposition` was given a target this module never registered as a managed host. * * The managed protocol is reached through the composition entry rather than off the host * instance, so the only admissible targets are the ones the host registers at construction. A * caller that gets this has an object that is not a host of this module — a plain object, a host * from a different copy of the module, or a value that was never constructed at all. */ readonly compositionTargetUnmanaged: 'COMPOSITION_TARGET_UNMANAGED';
};

export declare const PluginHostRegistrationLifecycle: {
  /** No installation/disposal hook is currently acquiring registration resources. */ readonly idle: 'idle';
  /** Current install attempt may acquire resources and stages before publication. */ readonly install: 'install';
  /** Registration capabilities are being revoked and released; new acquisition is rejected. */ readonly dispose: 'dispose';
};

export declare const PluginHostStatus: {
  /** Accepts new operations; existing registrations can publish through their normal guards. */ readonly active: 'active';
  /** Disposal closed admission; accepted work and cleanup may still be settling. */ readonly closing: 'closing';
  /** Logical terminal state; physicalCompletion can still describe outstanding cleanup. */ readonly disposed: 'disposed';
};

export declare const readPluginDependencies: (
  plugin: unknown,
) => readonly IPluginDependency[];

export declare const readPluginHostDisposalProvenance: (
  value: unknown,
) => IPluginHostDisposalProvenance | undefined;

export declare const createView: <TPlugin extends IPluginConstraint<any>>(
  token: IRegistrationToken<TPlugin>,
) => IRegistrationView<TPlugin>;

export declare const inspectFeatures: <TFeatures extends IFeatureRecord>(
  roots: TFeatures,
) => IFeatureInspection<TFeatures>;

export type IPluginHostCompositionIntegration<_THost> = Readonly<{
  /** Live committed revision, used to reject publication of a drifted prepared candidate. */ readonly revision: number;
  /** Captures current enabled publication; throws when the Host no longer accepts access. */ getCurrentSnapshot(): IPluginHostCompositionSnapshot;
  /** Captures a definition without running hooks and returns its immutable opaque admission. */ createPluginAdmission<
    TPlugin extends IPluginConstraint<any>,
  >(
    plugin: TPlugin,
  ): IPluginAdmission<TPlugin>;
  /** Allocates a stable name-matched stage lane; a second live slot for the same name is invalid. */ createDataOrderSlot(
    name: string,
  ): IPluginDataOrderSlot;
  /** Queues construction without publication; the owner must later commit or discard the capsule. */ prepareAdmissions(
    requestsInPublicationOrder: readonly IPluginAdmissionRequest[],
  ): Promise<IPluginPreparedAdmissions>;
  /** * Synchronously publishes one unused candidate if revision/lanes remain current; returns * receipts. */ commitPreparedAdmissions(
    prepared: IPluginPreparedAdmissions,
  ): readonly IRegistrationToken[];
  /** Rolls back an unpublished candidate; repeated or foreign discard returns empty cleanup detail. */ discardPreparedAdmissions(
    prepared: IPluginPreparedAdmissions,
  ): Promise<IPluginHostPhysicalCleanupResult>;
  /** Permanently retires this Host's lane; repeated retirement is harmless, foreign slots fail. */ retireDataOrderSlot(
    slot: IPluginDataOrderSlot,
  ): void;
  /** Captures exact live receipts, rejecting duplicates or an omitted required dependent. */ prepareUnUseBatch(
    receiptsInCleanupOrder: readonly IRegistrationToken[],
  ): IPluginPreparedRemovalBatch;
  /** Rechecks generations/dependencies, revokes all leaves, then waits for the fence and cleanup. */ commitPreparedUnUseBatch<
    TView,
  >(
    prepared: IPluginPreparedRemovalBatch,
    options: IPluginBatchRemovalOptions,
  ): Promise<IPluginBatchRemovalResult<TView>>;
}>;

export type IPluginHostCompositionSnapshot = Readonly<{
  /** Frozen extension publication with exact-registration liveness guards. */ readonly extensions: Readonly<
    Record<PropertyKey, unknown>
  >;
  /** Host config capability; reading a path still resolves current committed configuration. */ readonly config: IPluginHostConfigFor<
    readonly IPluginConstraint<any>[]
  >;
}>;

export type IRegistrationToken<
  TPlugin extends IPluginConstraint<any> = IPluginConstraint<any>,
> = object & Readonly<{ readonly __plugin?: TPlugin }>;

export type IRegistrationView<
  TPlugin extends IPluginConstraint<any> = IPluginConstraint<any>,
> = Readonly<{
  /** Exact-generation guarded extensions; they never follow a same-name replacement. */ readonly extensions: Readonly<
    IExtractPluginExt<TPlugin>
  >;
}>;

export declare const openComposition: (
  target: object,
) => IPluginHostCompositionIntegration<object>;

examples:
import { createRuntime } from '@migaia/reactive'

const runtime = createRuntime()
const price = runtime.signal(30)
const quantity = runtime.signal(2)
// 合计由单价和数量推导出来，不需要在每个修改的地方手动更新
const total = runtime.computed(() => price.value * quantity.value)

const render = runtime.effect(() => {
  console.log(`购物车合计：${total.value} 元`)
})

quantity.value = 3 // 改数量
runtime.flush() // 示例里手动冲刷；平时由微任务自动完成
price.value = 25 // 改单价
runtime.flush()

render.dispose()
total.dispose()

import { createRuntime } from '@migaia/reactive'

const runtime = createRuntime()
const room = runtime.signal('大厅')

const chat = runtime.effect(() => {
  const name = room.value
  console.log(`进入 ${name}`)
  // 返回的函数会在下次重跑之前、以及 dispose() 时执行
  return () => console.log(`离开 ${name}`)
})

room.value = '技术交流'
runtime.flush()
chat.dispose() // 用户关闭聊天窗口

import { createRuntime } from '@migaia/reactive'

const runtime = createRuntime()
const first = runtime.signal('Ada')
const last = runtime.signal('Lovelace')
const initials = runtime.computed(() => `${first.value[0]}.${last.value[0]}.`)
const label = runtime.computed(() => `${first.value} ${last.value}（${initials.value}）`)

let effectRuns = 0
const header = runtime.effect(() => {
  effectRuns += 1
  console.log('页头显示:', label.value)
})

// 同一段同步代码里改了两个值
first.value = 'Grace'
last.value = 'Hopper'
await Promise.resolve() // 等默认的微任务冲刷
console.log('副作用一共执行了', effectRuns, '次')
header.dispose()

import { createRuntime } from '@migaia/reactive'

const runtime = createRuntime()
const orders = runtime.signal([120, 80, 45])
let computations = 0
const report = runtime.computed(() => {
