  readonly disposed: boolean;
  debugName?: string;
  readonly deps: ReadonlySet<IObservable>;
  readonly depVersions: ReadonlyMap<IObservable, number>;
  markDirty(): void;
  onDependencyDisconnected(observable: IObservable): void;
};

export type IObserverBinding = {
  /** * Captures dependencies during render. * * Records the nodes read and their versions without creating dependency edges. Discarded renders * therefore leave no subscriptions. */ capture<
    R,
  >(
    read: () => R,
  ): ICapture<R>;
  /** * Install the binding-owned observer. Keeping the concrete Effect private prevents adapters from * mutating deps/versions or calling run/markDirty. */ observe(
    fn: () => void | IDisposer,
    options?: IReactiveNodeOptions,
  ): IDisposer;
  /** * Installs captured dependencies during commit. * * Three outcomes distinguish a required fresh capture from a missing observer. Invalidate the * snapshot and reread only for `stale`. Do not pull dirty nodes during commit, because evaluation * errors would bypass the Error Boundary. */ commit(
    capture: ICapture<unknown>,
  ): IObserverCommitResult;
  /** Force one committed observer run and report whether its dependency set changed. */ retrack(): IObserverRetrackResult;
};

export type IRuntimeFieldSource = {
  track(): void;
  notify(): void;
  commit<T>(write: () => T): T;
  readonly observed: boolean;
  readonly disposed: boolean;
  dispose(): void;
};

export type IRuntimeSourceBinding = Readonly<{
  /** Monotonic local graph version, advanced only by canonical source publication. */ readonly version: number;
  /** Live diagnostic view whose mutable backing set remains in the kernel. */ readonly subs: ReadonlySet<IObserver>;
  /** Lifecycle and update operations capture the original node without accepting another target. */ readonly source: IRuntimeFieldSource;
}>;

export type ITrackedObserverBinding = Readonly<{
  /** Read-only current dependencies maintained by the tracker. */ readonly deps: ReadonlySet<IObservable>;
  /** Read-only versions recorded during the last tracked execution. */ readonly depVersions: ReadonlyMap<
    IObservable,
    number
  >;
  /** Runs synchronous reads in this observer's dependency frame and preserves callback errors. */ runTracked<
    T,
  >(
    read: () => T,
  ): T;
  /** Disconnects this observer while keeping lifecycle policy with its owner. */ clear(): void;
  /** Removes reverse edges while retaining the dependency version snapshot. */ suspend(): void;
  /** Reports whether this observer has a retained suspended snapshot. */ isSuspended(): boolean;
  /** Pulls and compares the retained snapshot, reattaching unchanged dependencies. */ revalidate(): boolean;
  /** Pulls upstream dependencies and reports whether any recorded version changed. */ hasStaleDependencies(): boolean;
  /** Uses the runtime's admitted idle channel for this observer owner's work. */ deferIdle(
    task: () => void,
  ): void;
}>;

export declare const ReactiveErrorPhase: {
  readonly asyncFlush: 'async-flush';
  /** Reports a hostile action-error cause getter during batch flush failure reconciliation. */ readonly causeRead: 'cause-read';
  readonly dependencyDisconnect: 'dependency-disconnect';
  readonly lifecycleHook: 'lifecycle-hook';
  readonly ssrResource: 'ssr-resource';
  readonly subscriptionListener: 'subscription-listener';
  readonly traceListener: 'trace-listener';
};

