export type IResourceOptions<T = unknown> = {
  /** Human-readable owner label used in reactive diagnostics and request error context. */ debugName?: string;
  /** * Successful values remain fresh for this many milliseconds. `0` and `Infinity` keep them fresh * until a dependency changes or `refetch()` is called. */ ttl?: number;
  /** Start the first request in the constructor. Defaults to true. */ autoStart?: boolean;
  /** Keep stale success data visible while a background refresh runs. */ staleWhileRevalidate?: boolean;
  /** Retry count or predicate. Suspense Promise throws do not count. */ retry?: IResourceRetryPolicy;
  /** * Milliseconds to wait before the next retry, fixed or computed from the failure number and * error. Defaults to 0. */ retryDelay?:
    | number
    | ((failureCount: number, error: unknown) => number);
  /** Keep upstream reactive edges while no state consumer exists. */ keepAlive?: boolean;
  /** SSR/persisted success cache used before optional revalidation. */ initialSnapshot?: IResourceCacheSnapshot<T>;
  /** * Supplies one scheduler for TTL, `updatedAt`, `expiresAt`, and retry delays. Defaults to * utils/scheduler `systemScheduler`. Missing host capabilities fail immediately instead of * silently falling back to microtasks. */ scheduler?: IScheduler;
};

