export type IResourceRetryPolicy =
  | number
  | ((failureCount: number, error: unknown) => boolean);

export type IResourceSetupContext = {
  /** Runtime that owns the resource graph. */ readonly runtime: IRuntime;
  /** Scheduler the resource uses for TTL and retry timing. */ readonly scheduler: IScheduler;
  /** Aborts when the resource is disposed or setup fails; pass it to listeners and long work. */ readonly signal: IAbortSignal;
  /** Diagnostic name from the options, if any. */ readonly debugName:
    | string
    | undefined;
  /** * Registers a synchronous cleanup. Cleanups run in reverse order on `dispose()`, or immediately * when setup fails. Only valid while setup runs (`RESOURCE_SETUP_CLOSED` afterwards). Returns the * context for chaining. */ onDispose(
    cleanup: () => void,
  ): IResourceSetupContext;
};

export type IResourceState<T> =
  | { status: typeof ResourceStatus.idle }
  | { status: typeof ResourceStatus.pending }
  | { status: typeof ResourceStatus.success; data: T; refreshing?: boolean }
  | {
      status: typeof ResourceStatus.error;
      error: unknown;
    } /** * `error` is a native `DOMException` at runtime; typed as `Error` so declarations need no DOM * types. */
  | { status: typeof ResourceStatus.cancelled; error: Error };

