export type IResourceUpdater<T> = {
  bivarianceHack(previous: T | undefined): T;
}['bivarianceHack'];

export declare class Resource<T> implements IObserver, IDisposable {
  #private;
  /** Reactive nodes read synchronously by the last fetcher run. */ readonly deps: ReadonlySet<IObservable>;
  /** Dependency versions retained by the canonical reactive tracker. */ readonly depVersions: ReadonlyMap<
    IObservable,
    number
  >;
  /** Runtime that owns this Resource; disposing the Resource leaves it running. */ readonly runtime: IRuntime;
  /** Diagnostic label retained as an existing public own property. */ debugName?: string;
  /** * Validates every option once, restores `initialSnapshot` when given, and starts the first * request unless `autoStart` is false or the snapshot is still fresh. Invalid options throw * `INVALID_OPTION`; an invalid snapshot throws `INVALID_SNAPSHOT`. */ constructor(
    fetcher: IResourceFetcher<T>,
    runtime: IRuntime,
    options?: IResourceOptions<T>,
  );
  /** Reactive state-machine snapshot. Expired success values revalidate. */ get state(): IResourceState<T>;
  /** * Shared promise for the current request or fresh cached value. Multiple readers receive the same * promise; it starts work only when idle/stale. */ get promise(): Promise<T>;
  /** Whether `dispose()` has run; readable after disposal. */ get disposed(): boolean;
  /** True while a fresh request runs without hiding an existing success value. */ get refreshing(): boolean;
  /** Transport status, separate from the visible data/error state. */ get fetchStatus(): ResourceFetchStatus;
  /** Whether the currently cached success value has crossed its TTL. */ get isStale(): boolean;
  /** Whether reactive consumers currently observe this resource's state. */ get observed(): boolean;
  /** * Suspense-compatible read: returns cached data, throws the active Promise while pending, and * throws the fetch error after failure. */ read(): T;
  /** * Reads without tracking, with the same result semantics as `read()`. Success returns data, * pending throws a Promise, and failure throws the error. It creates no dependency edges and does * not check freshness or start a request. `React` snapshot reads and external diagnostics can * inspect current state without entering another consumer's tracking window. */ peek(): T;
  /** Inspects the canonical state without tracking, starting work or revalidating TTL. */ peekState(): IResourceState<T>;
  /** Cancels this generation and drops its cache; the same Resource can start again from idle. */ reset(): void;
  /** * Force a new request. Explicit refetches do not reuse a fresh cache entry; passive * `promise`/`read()` consumers do. */ refetch(): Promise<T>;
  /** Mark cached data stale and immediately start a replacement request. */ invalidate(): Promise<T>;
  /** Cancel only the active generation; the Resource remains reusable. */ cancel(): void;
  /** Captures duration metadata without serializing or copying the caller-owned data. */ dehydrate():
    | IResourceCacheSnapshot<T>
    | undefined;
  /** Rebases captured durations into this scheduler; transport/storage elapsed time is caller-owned. */ hydrate(
    snapshot: IResourceCacheSnapshot<T>,
  ): void;
  /** * Replaces the visible data locally (optimistic update, server push, cache write). Supersedes any * in-flight request so its late result cannot overwrite this value, and starts a fresh TTL * window. An updater receives the current success data (or `undefined`). Function-typed data must * be passed through an updater. Returns `this` for chaining. * * @example * ;```ts * todos.mutate((list = []) => [...list, draft]) * ``` */ mutate(
    next: T | IResourceUpdater<T>,
  ): this;
  /** * Calls `listener` with the current state now and after every state change, for consumers that do * not run inside the reactive graph. Subscribing counts as observation (it can start and keep * requests alive). Listener throws are reported through `runtime.reportError` and do not stop * delivery. Returns an idempotent unsubscribe; `dispose()` unsubscribes automatically. * * @example * ;```ts * const stop = user.subscribe((state) => render(state)) * ``` */ subscribe(
    listener: (state: IResourceState<T>) => void,
  ): () => void;
  /** * Derived reactive value from the success data; `undefined` while not in success. The computed is * disposed together with this resource. * * @example * ;```ts * const count = todos.select((list) => list.length) * count.value // number | undefined * ``` */ select<
    R,
  >(selector: (data: T) => R): IReactiveComputed<R | undefined>;
  /** Same as `dispose()`; enables `using resource = createResource(...)`. */ [Symbol.dispose](): void;
  /** A reactive dependency changed. Coalesce diamond/batched invalidations. */ markDirty(): void;
  /** A dependency was disposed; force re-evaluation so failure is observable. */ onDependencyDisconnected(): void;
  /** * Ends the resource: aborts the running request, clears dependencies and releases the state node. * Idempotent. Later reads and requests throw `RESOURCE_DISPOSED`; the first cleanup failure is * thrown with any later ones attached to its `errors`. */ dispose(): void;
}

