  ): void;
  extensions?: readonly string[];
  requiredExtensions?: readonly string[];
  /** Installed media protection may narrow physical native storage; it cannot grant capability. */ nativeBinary?: false;
  /** The installed wire protection owner lends this cold native-transfer safety fact before getters. */ transferRequiresIntegrity?: true;
  /** Only a genuine installed protection owner describes its observable authentication mode. */ observationFacts?: Readonly<
    Pick<IRpcProbeDescriptor, 'authentication'>
  >;
  dispose?: IRpcDispose;
  /** Native namespace publication rejects collisions with host methods. */ namespaceExtensions?(
    namespace: string,
  ): Readonly<E>;
}>;

examples:
import { defineHost } from '@migaia/plugin-host'
import {
  rpcHostPipelines,
  rpcFlowPlugin,
  type IRpcFlowFeature,
  type IRpcFlowPlugin,
  type IRpcTransportPlugin
} from '@migaia/rpc-host/sdk'

/** Capture lazy authority callbacks before the real host is assigned. */
const rpc = rpcHostPipelines(
  () => host,
  (name, request) => host.pipeline(name, request)
)
/** One native owner supplies both stage registration and execution. */
export const host = defineHost({
  domainCore: rpc.domainCore,
  host: { execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false } }
})

/** Commit reusable flow definitions before opening any transport resource. */
export async function installRpc(
  features: readonly IRpcFlowFeature<object>[],
  observers: readonly IRpcFlowPlugin[],
  transports: readonly IRpcTransportPlugin[]
) {
  await host.use(...observers, rpcFlowPlugin(features))
  await host.use(...transports)
}

