  /** Actual plugin stages may publish readonly facts through the existing observer boundary. */ observe?(
    event: IRpcObservation,
  ): void;
  /** Namespace extensions can originate a normal host call without accessing mutable work tables. */ call(
    namespace: string,
    command: ICallCommand,
    options?: IRpcCallOptions,
  ): Promise<unknown>;
  /** Policy owners retire an observed exact carrier through the actual Session lifecycle owner. */ retire(
    carrierId: string,
    reason?: unknown,
    kind?: RpcSessionRetirement,
  ): Promise<void>;
}>;

