    /** False removes one logical member's signal while retaining the Session's close fence. */ signal?:
      | IAbortSignal
      | false;
    /** Physical transfer authority retains the original native backing identities. */ transfer?: readonly ArrayBuffer[];
    /** Called at the actual carrier write boundary, including each surviving batch member. */ onWriteStart?(): void;
