  /** An acquired native connection may already own a distinct stable session identifier. */ sessionId?: string;
  /** Query the original native source's current sole-reader ownership after subscription. */ isExclusive?(): boolean;
  /** Parent-assigned identity wins; an omitted name preserves the child's configured/default name. */ self?: Readonly<{
    name?: string;
    instanceId: string;
  }>;
