  return createRpcHost<IWorkerApi, typeof plugins>({ plugins })
}

export function call(host: ITaskHost, target: string, signal: AbortSignal) {
  return host.coroutine.send(target, 'echo', 'hello', {
    signal,
    timeout: timeoutFeature({ ms: 500 }),
    retry: false
  })
}

