  /** * Defaults to the host `TextDecoder`, explicitly requiring the Encoding API. Fixed at * construction. Parser-specific decoding remains owned by the parser; this option does not * replace a JSON plugin's own decoder configuration. */ readonly decoder?: ITextDecoder;
  /** * Optional cleanup error policy. Defaults to `{ policy: 'throw' }`. The report policy requires a * reporter. */ readonly cleanup?:
