    ctx?: IOperationContext & IWriteConcurrencyOptions,
  ): Promise<void>;
  /** Clears this store's public value channels; structured extensions also clear bytes and records. */ clearAll(
    ctx?: IOperationContext & IWriteConcurrencyOptions,
