export type IEntityIndex<TDomain> =
  | {
      /** Domain property path whose value becomes the index key. */ readonly path: IObjectPathInput<TDomain>;
      /** Defaults to false; true rejects conflicting projected keys inside the authoritative commit. */ readonly unique?: boolean;
      /** * Defaults to false; true projects individual array elements and is unavailable for composite * paths. */ readonly multiEntry?: boolean;
      /** * Projection revision; path projections default to 1, while custom select must supply a * positive revision. */ readonly revision?: number;
    }
  | {
      /** Ordered domain paths forming one composite array key. */ readonly paths: readonly IObjectPathInput<TDomain>[];
      /** Defaults to false; true rejects conflicting projected keys inside the authoritative commit. */ readonly unique?: boolean;
      /** * Defaults to false; true projects individual array elements and is unavailable for composite * paths. */ readonly multiEntry?: false;
      /** * Projection revision; path projections default to 1, while custom select must supply a * positive revision. */ readonly revision?: number;
    }
  | {
      /** * Synchronous projection returning a single key, multiple keys or undefined to omit this * record. */ readonly select: (
        value: TDomain,
      ) =>
        | { readonly kind: 'single'; readonly key: IStorageKey }
        | { readonly kind: 'multiple'; readonly keys: readonly IStorageKey[] }
        | undefined;
      /** Defaults to false; true rejects conflicting projected keys inside the authoritative commit. */ readonly unique?: boolean;
      /** * Projection revision; path projections default to 1, while custom select must supply a * positive revision. */ readonly revision: number;
    };

export type IEntityIndexMap<
  TDomain,
  TIndexes extends IEntityIndexDefinitions<TDomain> = IEntityIndexDefinitions<TDomain>,
> = Readonly<{
  [TName in keyof TIndexes & string]: IEntityIndexQueryKey<TDomain, TIndexes[TName]>;
}>;

export type IEntityListOrder<TDomain> =
  | { readonly orderBy?: never; readonly limit?: number }
  | { readonly orderBy: IRecordComparator<TDomain>; readonly limit: number };

export type IEntityOptions<
  TDomain,
  TStored = TDomain,
  TIndexes extends IEntityIndexDefinitions<TDomain> | undefined = undefined,
> = {
  /** * Explicit optional units imported from the entity capability subpaths; omitted means basic reads * and writes only. */ readonly features?: readonly IEntityFeature[];
  /** Nonempty entity namespace; names beginning with the reserved __ prefix are rejected. */ readonly name: string;
  /** Names the domain object property used as its primary key. */ readonly key: Extract<
    keyof TDomain,
    string
  >;
  /** Defaults to `passthrough`, which returns values without validation. */ readonly schema?: ISchemaAdapter<
    TDomain,
    TStored
  >;
  /** * Applies on every backend through `selectCodec` using `store.capabilities`. Structured backends * do not bypass an explicitly configured codec. When omitted, IndexedDB and memory default to * `structuredCodec`, preserving objects through native structured cloning. Key-value-only * backends default to `jsonCodec`. */ readonly codec?: ICodec<
    unknown,
    unknown
  >;
  /** Positive safe-integer envelope version; defaults to 1. */ readonly version?: number;
  /** * Complete own step table from version 2 through the configured version; omitted only for version * 1. */ readonly migrations?: Readonly<
    Record<number, IMigrationStep>
  >;
  /** * Defaults to `true` because persisted data survives version changes, making invalid reads more * common than invalid writes. */ readonly validateOnRead?: boolean;
