    message: string,
  ) => void;
  /** Optional default domain comparator; omission orders by the canonical primary key. */ readonly defaultOrderBy?: IRecordComparator<TDomain>;
  /** Secondary projections are entity-owned and backend-neutral. */ readonly indexes?: TIndexes;
