export type IEntityTransactionScope<
  TDomain,
  TIndexes extends Readonly<Record<string, IStorageKey>> = Readonly<
    Record<never, IStorageKey>
  >,
  TAugmentMethods extends object = {},
> = IEntityQueryAccess<TDomain, TIndexes, undefined, false, TAugmentMethods> & {
