    IEntityListOrder<TRecord> & {
      /** Exact declared index name whose projection determines the range key type. */ readonly index: TName;
      /** Optional range in the chosen index's projected key domain. */ readonly range?: IKeyRange<
        TIndexes[TName] & IStorageKey
