export type IInvalidRecordHandler<TRecord = unknown> = (
  issue: IInvalidRecordIssue<TRecord>,
) => IInvalidRecordAction;

export type IInvalidRecordIssue<TRecord = unknown> = {
  /** Logical record key associated with the failure. */ readonly key: IStorageKey;
  /** Original raw stored value inspected by this read. */ readonly raw: unknown;
  /** Materialized domain value when one was available before failure. */ readonly record?: TRecord;
  /** Decode, migrate or validate phase that failed. */ readonly stage: IStorageRecordStage;
  /** Original extension or decoding failure. */ readonly cause: unknown;
};

export type IListOptions<
  TRecord = unknown,
  TKey extends IStorageKey = IStorageKey,
> = IEntityListOrder<TRecord> & {
  /** * V2 record keys isolate the entity first. Legacy records require a full-store scan until * explicit migration. */ readonly range?: IKeyRange<TKey>;
  /** Indexed queries use IIndexedListOptions so their index key remains correlated. */ readonly index?: never;
  /** Next by default, or prev for reverse key traversal. */ readonly direction?:
    | 'next'
    | 'prev';
  /** * Skip by default, throw to fail on an invalid record, or a synchronous handler returning either * action. */ readonly onInvalid?:
    | IInvalidRecordAction
    | IInvalidRecordHandler<TRecord>;
};

export type IMigrateOptions<TRecord = unknown> = {
  /** Positive safe-integer persistence batch size; defaults to 100. */ readonly batchSize?: number;
