    | IInvalidRecordAction
    | IInvalidRecordHandler<TRecord>;
};

export type IMigrateResult = {
  /** Physical candidate records examined. */ readonly scanned: number;
  /** Records admitted as candidates for this entity migration. */ readonly eligible: number;
  /** Records whose upgraded envelope was actually committed. */ readonly migrated: number;
  /** Invalid records skipped by the selected policy. */ readonly skipped: number;
  /** Records already at the current version when observed. */ readonly alreadyCurrent: number;
  /** Records still conflicting after the existing per-record retry path. */ readonly conflicted: number;
