  /** Validate/normalize/encode one value and commit it, returning the normalized primary key. */ put(
    value: TDomain,
    ctx?: IOperationContext & IWriteConcurrencyOptions,
  ): Promise<IStorageKey>;
  /** Remove this entity's record for the supplied logical id. */ remove(
    id: IStorageKey,
    ctx?: IOperationContext & IWriteConcurrencyOptions,
  ): Promise<void>;
  /** * Scans V2 structured records by their physical entity prefix and filters with the shared * comparator. Legacy records temporarily require a full-store scan. */ list(
    options?: IListOptions<TDomain> | IIndexedListOptions<TDomain, TIndexes>,
    ctx?: IOperationContext,
  ): Promise<TDomain[]>;
  /** Iterate materialized query results; early return releases the iterator's operation resources. */ stream(
    options?: IListOptions<TDomain> | IIndexedListOptions<TDomain, TIndexes>,
    ctx?: IOperationContext,
