    value: unknown,
    ctx?: IOperationContext,
  ): Promise<TDomain>;
  /** * Converts a domain object to its stored representation. Without this method, the value passes * through unchanged. */ encode?(
    value: TDomain,
    ctx?: IOperationContext,
  ): Promise<TStored>;
  /** * Converts a stored representation to its domain object. Without this method, the value passes * through unchanged. */ decode?(
    raw: TStored,
    ctx?: IOperationContext,
  ): Promise<TDomain>;
  /** * Optionally normalizes before writing. Without this method, the validated value passes through * unchanged. */ normalize?(
    value: TDomain,
    ctx?: IOperationContext,
  ): Promise<TDomain>;
