export type IArchiveApi<N extends string = 'archive'> = {
  [K in `${N}${typeof Archive.runSuffix}`]: (
    options?: IArchiveRunOptions,
  ) => Promise<IArchiveRunResult>;
} & {
  [K in `${N}${typeof Archive.getSuffix}`]: (
    key: string,
    options?: IArchiveGetOptions,
  ) => Promise<ICollectionsCodecValue | undefined>;
} & {
  [K in `${N}${typeof Archive.sweepSuffix}`]: (
    ctx?: IOperationContext,
  ) => Promise<IArchiveSweepResult>;
};

export type IArchivePluginOptions<T = ICollectionsCodecValue> = {
  readonly id: string;
  readonly hot: string;
  readonly cold: string;
  readonly rules: readonly IArchiveRule<T>[];
};

export type IArchiveRule<T = ICollectionsCodecValue> = {
  readonly name: string;
  readonly prefix: string;
  readonly where: (cutoffMs: number) => IWhere<T>;
  readonly olderThanMs: number;
  readonly segmentBytes?: number;
};

export type IArchiveRunOptions = IOperationContext & {
  readonly rule?: string;
  readonly limit?: number;
};

export type IArchiveRunResult = {
  readonly archived: number;
  readonly skipped: number;
  readonly segments: number;
};

export type IArchiveSweepResult = {
  readonly scanned: number;
  readonly removed: number;
};

export type IExtensionStage = NonNullable<
  import('@migaia/storage-host').IStorageErrorDetails['extensionStage']
>;

export type INamespaceCodec = {
  /** * Map a logical namespace/key pair to a physical string; a custom codec owns collision safety and * migration. */ encode(
    namespace: string,
    key: string,
  ): string;
  /** Return this namespace's logical key, or undefined for a foreign/malformed physical name. */ decode(
    namespace: string,
    physicalKey: string,
  ): string | undefined;
  /** Encode typed batch keys without colliding with the codec's original string-key layout. */ encodeStorageKey?(
    namespace: string,
    key: IStorageKey,
  ): string;
  /** Identify typed and string entries during namespace-wide cleanup and prefix deletion. */ decodeStorageKey?(
    namespace: string,
    physicalKey: string,
  ): IStorageKey | undefined;
};

export type IStorageErrorDetails = {
  /** Backend whose operation failed, when known. */ readonly backend?: IBackendKind;
  /** Logical key associated with this failure. */ readonly key?: string | IStorageKey;
  /** Channel already occupying a conflicting logical key. */ readonly existingChannel?: IStorageChannel;
  /** Channel the rejected mutation attempted to use. */ readonly attemptedChannel?: IStorageChannel;
  /** Schema, codec, migration, comparator or diagnostic extension that failed. */ readonly extensionStage?: IExtensionStage;
  /** Operation name attached by the owning boundary. */ readonly operation?: string;
  /** Original failure retained for bounded cause-chain inspection. */ readonly cause?: unknown;
};

