    cachePlugin(
      { tiers: [{ backend: 'values', ttlMs: 30000 }] },
      {
        semantic: semanticCacheFeature({
          backend: 'vectors',
          collection: 'answers',
          dimensions: 2,
          metric: 'cosine',
          minScore: 0.8,
          ttlMs: 30000,
          embed: async () => [1, 0]
        })
      }
    )
  )
