  })
  const items = host
    .backend('postgres')
    .use(vector)
    .collection<{ category: string }>('example-documents', { dimensions: 3, metric: 'cosine' })
  await items.upsert([{ id: 'guide', vector: [1, 0, 0], payload: { category: 'guide' } }])
  const hits = await items
    .near([1, 0, 0])
    .where({ category: 'guide' })
    .topK(20)
