  schedulerStrategy: (run) => run(),
  onError: (error) => {
    reports.push(error)
  }
})
const store = createStore({ count: 0 }, { runtime })
const original = new TypeError('诊断快照失败')
let fail = false
const tools = createStoreDevTools(store, {
