export type IActionTrace = {
  /** Configured now() value taken when this action is appended, not the trace event's timestamp. */ timestamp: number;
  /** Runtime action name or a caller-selected manual name. */ name: string;
  /** Optional manual diagnostic payload; automatic action capture does not add one. */ payload?: unknown;
  /** Optional duration supplied by the Runtime trace or manual caller. */ durationMs?: number;
  /** Optional original failure reference, populated automatically for action error events. */ error?: unknown;
};

export type IDependencyTreeNode = {
  /** Traversal role: dependency roots are observers and reverse-tree roots are observables. */ kind: (typeof StoreDevtoolsNodeKind)[keyof typeof StoreDevtoolsNodeKind];
  /** DebugName, then constructor.name, then AnonymousReactiveNode; not a stable node identifier. */ label: string;
  /** Current version on observable-role nodes; observer-role nodes omit this field. */ version?: number;
  /** Edges in the graph's current iteration order, truncated at maxDepth or a path cycle. */ children: IDependencyTreeNode[];
  /** Present as true only when this node repeats on the current path, not for a shared diamond leaf. */ circular?: boolean;
};

export type IStoreDevTools = {
  /** A fresh frozen chronological array of retained shallow-frozen history entries. */ readonly history: readonly IStoreHistoryEntry[];
