import { createRuntime } from '@migaia/reactive'
import { atomDef, createAtomStore, focusDef } from '@migaia/store-keyed'

const profileDef = atomDef({ name: 'Ada', avatar: 'a.png', online: true }, 'profile')
// 只关心名字的组件订阅这个字段，而不是整个资料对象
