  commitCapture(capture: IResourceCapture): () => void;
  /** Releases the resource once no holder remains; with holders left it waits in `closing`. */ dispose(): void;
  /** Releases the resource now, ignoring holders. */ forceDispose(): void;
  /** Resolves once this resource reaches its terminal state. Never depends on GC. */ whenTerminal(): Promise<void>;
  /** Calls `listener` after every state change; returns the unsubscribe function. */ subscribe(
    listener: () => void,
