export type IDevToolsAdapter<S> = {
  /** Initialize from current state at installation and again for commit commands. */ init(
    state: S,
  ): void;
  /** Receive an event and current host state at this stage's position in the flat pipeline. */ send(
    event: IMiddlewareEvent<S>,
    state: S,
  ): void;
  /** Register normalized commands and synchronously return the disposer owned by plugin cleanup. */ subscribe?(
    listener: (command: IDevToolsCommand<S>) => void,
  ): IDisposer;
};

export type IDevToolsCommand<S> =
  | {
      /** Apply a selected historical state through runAction. */ readonly type: typeof MiddlewareCommandType.jump;
      /** Parsed or adapter-provided state; no schema validation is implied. */ readonly state: S;
    }
  | {
      /** Apply the adapter's reset state through runAction. */ readonly type: typeof MiddlewareCommandType.reset;
      /** Adapter-provided replacement state, not an implicit initial-state cache. */ readonly state: S;
    }
  | {
      /** Reinitialize the adapter with current host state, without applying a new state. */ readonly type: typeof MiddlewareCommandType.commit;
    };

export type IMiddlewareActionEvent =
  | {
      /** Identifies an action notification rather than a state or error event. */ readonly type: typeof MiddlewareEventType.action;
      /** The synchronous action is about to run; no duration is available yet. */ readonly phase: typeof MiddlewareEventPhase.start;
      /** Caller action label, reused by its corresponding end/error notification. */ readonly name: string;
      /** Wall-clock milliseconds at notification creation. */ readonly timestamp: number;
      /** Optional caller metadata retained by reference, without cloning or runtime freezing. */ readonly metadata?: Readonly<
        Record<string, unknown>
      >;
    }
  | {
      /** Identifies an action notification. */ readonly type: typeof MiddlewareEventType.action;
      /** The callback returned, even if that return value is a still-pending Promise. */ readonly phase: typeof MiddlewareEventPhase.end;
      /** Same caller label as the action's start notification. */ readonly name: string;
      /** Wall-clock milliseconds at notification creation. */ readonly timestamp: number;
      /** Elapsed synchronous action time; not the settlement time of a returned Promise. */ readonly durationMs: number;
      /** Optional caller metadata, retained by reference. */ readonly metadata?: Readonly<
        Record<string, unknown>
      >;
    }
  | {
      /** Identifies an action notification. */ readonly type: typeof MiddlewareEventType.action;
      /** The synchronous callback threw; asynchronous rejections are not captured here. */ readonly phase: typeof MiddlewareEventPhase.error;
      /** Same caller label as the action's start notification. */ readonly name: string;
      /** Wall-clock milliseconds at notification creation. */ readonly timestamp: number;
      /** Elapsed synchronous time before the failure. */ readonly durationMs: number;
      /** Failure rethrown by the action boundary, retaining its original identity or cause. */ readonly error: unknown;
