  /** Optional producer metadata retained by reference. */ readonly metadata?: Readonly<
    Record<string, unknown>
  >;
};

export type IMiddlewareEvent<S> =
  | IMiddlewareActionEvent
  | IMiddlewareStateEvent<S>
