    Record<string, unknown>
  >;
};

export type IReduxDevToolsConnection<S> = {
  /** Initialize or recommit the current state. */ init(state: S): void;
  /** Receive a generated action label/event object and current state. */ send(
    action: unknown,
    state: S,
  ): void;
  /** Register wire messages and return the exact cleanup function to pass through to consumers. */ subscribe(
    listener: (message: IReduxDevToolsMessage) => void,
  ): IDisposer;
