  /** * Synchronously marks the handler unavailable by setting `disposed = true`. It does not release * the endpoint. Repeated calls have no additional effect. */ close(): void;
  /** Admitted inbound deliveries still awaiting setup/dispatch, not active compute or drain count. */ readonly pendingCount: number;
  /** Terminal admission marker, set synchronously before asynchronous endpoint cleanup. */ readonly disposed: boolean;
};

export type IWorkerComputedOptions<Output> = IResourceOptions<Output> & {
  /** Borrowed reactive Runtime, default defaultRuntime, used for the returned Resource. */ readonly runtime?: IRuntime;
};

