  /** * A worker adapter is called after disposal. * * Create a new adapter instead of reusing the disposed instance. */ readonly adapterDisposed: 'ADAPTER_DISPOSED';
  /** * Worker serialization is cooperatively cancelled through an `AbortSignal` or explicit stream * stop. * * Treat this as cancellation. Transfer can detach input after a send, but pre-cancelled requests * have not sent it; inspect the actual backing buffer before deciding whether retry is safe. */ readonly requestAborted: 'REQUEST_ABORTED';
  /** * A request chunk sent to the worker has an invalid shape. * * Check that the payload satisfies `ISerializeChunk`. This is a protocol error. */ readonly invalidRequestChunk: 'INVALID_REQUEST_CHUNK';
  /** * A chunk returned by the worker has an invalid shape. * * Check the worker parser output. This is a worker implementation error. */ readonly invalidResponseChunk: 'INVALID_RESPONSE_CHUNK';
  /** * Both endpoint and owned Worker cleanup failed during parser disposal. A single failure keeps * its existing identity rather than receiving this aggregate code. The caller must inspect * `cause`/`errors[]` and treat the parser as terminal. */ readonly cleanupFailed: 'CLEANUP_FAILED';
};

export declare class WorkerAdapter {
  #private;
  /** * Borrows port and captures client options once; options default to an empty object. clientId * defaults to main, with worker as the remote endpoint id. timeoutMs is omitted by default, * leaving requests without an application deadline. Invalid options throw locally; endpoint setup * failures surface through request/dispose rather than making the constructor async. */ constructor(
