let running = 0
const exportFile = (name: string) =>
  createCoroutineSupervisor({
    id: `export-${name}`,
    budget,
    spec: {
      task: async () => {
        running += 1
        console.log(`开始导出 ${name}，同时运行: ${running}`)
        await new Promise((resolve) => setTimeout(resolve, 100))
        running -= 1
      }
    },
    restart: { mode: 'never' },
    report: console.error
  })

