  /** No runtime property is emitted; each facade keeps its source and plugin tuples in declarations. */ readonly [trayHostTypes]: Readonly<{
    readonly host: THost;
    readonly definitions: TDefinitions;
    readonly ready: TReady;
  }>;
  /** Frozen current definition names, including blocked definitions. */ readonly plugins: readonly string[];
  /** Frozen names whose current Graph nodes are ready. */ readonly readyPlugins: readonly string[];
  /** Managed facade lifecycle, independent of per-plugin readiness. */ readonly state: ITrayHostState;
  /** Whether the facade is currently active. */ readonly isActive: boolean;
  /** Retained disposal failure; ordinary mutation failures are returned in their own observations. */ readonly error:
    | unknown
    | undefined;
  /** Current Host extension snapshot, including constructor baseline and ready managed plugins. */ readonly extensions: Readonly<
    IMergePluginExts<readonly [...IHostBaselinePlugins<THost>, ...TReady]>
  >;
  /** Config access delegates to the canonical PluginHost snapshot and update owner. */ readonly config: IPluginHostConfigFor<
    readonly [...IHostBaselinePlugins<THost>, ...TReady]
  >;
  /** * Reads Graph node state, using blocked for an unknown name; publication/bypass checks still * apply. */ pluginState(
    name: string,
  ): string;
  /** Subscribes to managed observations and returns a synchronous unsubscribe receipt. */ on<
    TKey extends keyof ITrayHostEventMap,
