  /** Successful committed definition removal. */ readonly unUse: Readonly<
    Record<string, unknown>
  >;
  /** Successful same-name definition replacement. */ readonly replace: Readonly<
    Record<string, unknown>
  >;
  /** Settled lifecycle aliases describe the logical operation without exposing Graph authority. */ readonly registered: Readonly<
    Record<string, unknown>
  >;
  /** Alias of the successful unUse observation. */ readonly removed: Readonly<
    Record<string, unknown>
  >;
  /** Alias of the successful replace observation. */ readonly replaced: Readonly<
    Record<string, unknown>
  >;
  /** * Graph-stage mutation failure; earlier descriptor/admission rejection does not publish this * event. */ readonly mutationFailed: Readonly<{
