    /** Same primary error exposed by the failure result. */ readonly error: Error;
  }>;
  /** Published after the shared disposal Promise exists, allowing safe reentrant observation. */ readonly disposing: Readonly<{
    readonly state: 'closing';
  }>;
  /** Logical disposal observation; cleanupComplete does not imply that cleanup had no errors. */ readonly disposed: Readonly<{
    readonly state: 'terminal';
    readonly cleanupComplete: boolean;
  }>;
};

export type ITrayPluginConstraint<THost extends ITrayHostSource> = IPluginConstraint<
  ITrayPluginCore<THost>
>;

export type ITrayPluginMutationObservation<TView> = ICleanupResult &
  Readonly<{
    /** Definition registration or same-name replacement. */ readonly operation:
      | 'use'
      | 'replace';
    /** Target definition name. */ readonly name: string;
    /** Names reported by Graph reconciliation for this operation. */ readonly affected: readonly string[];
    /** Whether successful reconciliation changed the Graph topology. */ readonly topologyChanged: boolean;
    /** Continue through this view to retain the resulting ready-plugin type information. */ readonly view: TView;
    /** Whether physical cleanup has settled; false requires observing physicalCompletion. */ readonly cleanupComplete: boolean;
  }>;

export type ITrayPluginMutationResult<
  TPreviousView,
  TSuccessView,
  TCommittedFailureView,
> =
  | (ITrayPluginMutationObservation<TSuccessView> &
      Readonly<{ readonly ok: true; readonly committed: true }>)
  | (ITrayPluginMutationObservation<TPreviousView> &
      Readonly<{
        readonly ok: false;
        readonly committed: false;
        readonly error: Error;
      }>)
  | (ITrayPluginMutationObservation<TCommittedFailureView> &
      Readonly<{
        readonly ok: false;
        readonly committed: true;
        readonly error: Error;
      }>);

export type ITrayPluginRemovalObservation<TView> = ICleanupResult &
  Readonly<{
    /** Requested definition name, including an unknown-name no-op. */ readonly name: string;
    /** Names reconciled by the removal; empty when no definition existed. */ readonly affected: readonly string[];
    /** Managed view after the removal or retained after failure. */ readonly view: TView;
    /** Whether physical cleanup has settled; inspect cleanupErrors separately. */ readonly cleanupComplete: boolean;
  }>;

export type ITrayPluginRemovalResult<TPreviousView, TCommittedView> =
  | (ITrayPluginRemovalObservation<TPreviousView> &
      Readonly<{
        readonly ok: true;
        readonly committed: false;
        readonly removed: false;
      }>)
  | (ITrayPluginRemovalObservation<TCommittedView> &
      Readonly<{ readonly ok: true; readonly committed: true; readonly removed: true }>)
  | (ITrayPluginRemovalObservation<TPreviousView> &
      Readonly<{
        readonly ok: false;
        readonly committed: false;
        readonly removed: false;
        readonly error: Error;
      }>)
  | (ITrayPluginRemovalObservation<TCommittedView> &
      Readonly<{
        readonly ok: false;
        readonly committed: true;
        readonly removed: true;
        readonly error: Error;
      }>);

export declare const TrayHostState: {
  /** Accepts managed mutations and Runtime leases. */ readonly active: 'active';
  /** Disposal has closed mutation admission while cleanup runs. */ readonly closing: 'closing';
  /** Logical disposal completed; the result may still expose physicalCompletion. */ readonly terminal: 'terminal';
  /** Disposal itself failed; inspect the facade error and returned cleanup observation. */ readonly failed: 'failed';
