export declare class ConfigOwner<T extends IConfigRecord = IConfigRecord> {
  #private;
  /** * Owns a copy of `value` (validated by `ownConfig`). Throws the `ownConfig` errors for invalid * roots and `CONFIG_VALIDATION_FAILED` when the validator rejects the initial value. */ constructor(
    value: T,
    options?: IConfigOwnerOptions<T>,
  );
  /** * Parses JSON text; malformed text retains `CONFIG_PARSE_FAILED` and its original cause. The * constructor rejects non-record roots with `CONFIG_UNSUPPORTED`. */ static from<
    T extends IConfigRecord = IConfigRecord,
  >(text: string, options?: IConfigOwnerParseOptions<T>): ConfigOwner<T>;
  /** * Loads a value, Promise or signal-aware factory; strings are parsed as JSON. Factory failures * retain their cause under `CONFIG_SOURCE_FAILED`; abort and timeout use the standard errors. */ static fromAsync<
    T extends IConfigRecord = IConfigRecord,
  >(
    source: IConfigAsyncSource<T>,
    options?: IConfigOwnerAsyncOptions<T>,
  ): Promise<ConfigOwner<T>>;
  /** * Builds nested data from flat environment variables, applying optional key/coerce policies. * Conflicting leaf/prefix keys throw `CONFIG_CONFLICT` before owner publication. */ static fromEnv<
    T extends IConfigRecord = IConfigRecord,
  >(
    env: Readonly<Record<string, string | undefined>>,
    options?: IConfigOwnerEnvOptions<T>,
  ): ConfigOwner<T>;
  /** Merges sources left to right into a new owner (later sources win, records merge deeply). */ static merge<
    S extends readonly [IConfigSource, ...IConfigSource[]],
  >(...sources: S): ConfigOwner<IMergedConfig<S>>;
  /** Brand check: `true` only for real `ConfigOwner` instances. */ static is(
    value: unknown,
  ): value is ConfigOwner;
  /** Whether writes are rejected after `lock()`. */ get locked(): boolean;
  /** Value at a typed path as a deep readonly view, or `undefined` when missing. */ get<
    const P extends IConfigOwnerPath<T>,
  >(path: P): IConfigView<IConfigOwnerPathValue<T, P>> | undefined;
  /** Value at a path, or `fallback` when the path is missing. */ getOr<
    const P extends IConfigOwnerPath<T>,
    D,
  >(path: P, fallback: D): IConfigView<IConfigOwnerPathValue<T, P>> | D;
  /** Value at a path; throws `CONFIG_VALUE_MISSING` when missing. */ require<
    const P extends IConfigOwnerPath<T>,
  >(path: P): IConfigView<IConfigOwnerPathValue<T, P>>;
  /** Discriminated read that tells a missing path from an own `undefined` value. */ read(
    path: IConfigOwnerPath<T>,
  ): IConfigReadResult;
  /** Whether the path has an own value (which may be `undefined`). */ has(
    path: IConfigOwnerPath<T>,
  ): boolean;
  /** Deep readonly view of the current snapshot; writes through it throw `CONFIG_READONLY`. */ view(): IConfigView<T>;
  /** New owner for a record subtree, sharing options but not listeners or the validator. */ select<
    const P extends IConfigOwnerPath<T>,
  >(path: P): ConfigOwner<IConfigOwnerPathValue<T, P> & IConfigRecord>;
  /** Paths that differ between this snapshot and `other` (`added` = only in `other`). */ diff(
    other: IConfigSource,
  ): readonly IConfigDiffEntry[];
  /** Whether `other` has the same data (deep, own keys). */ equals(
    other: IConfigSource,
  ): boolean;
  /** * Sets one path with copy-on-write; missing intermediate records are created. Throws * `CONFIG_PATH_INVALID` when an intermediate is not a record or array. */ set<
    const P extends IConfigOwnerPath<T>,
  >(path: P, value: IConfigOwnerWriteValue<T, P>): this;
  /** Deletes one path; deleting a missing path is a no-op. Array items are removed by index. */ delete(
    path: IConfigOwnerPath<T>,
  ): this;
  /** Applies a root-level overlay through `patchConfig` (`CONFIG_DELETE` removes a key). */ patch(
    patch: IConfigPatch<T>,
    options?: IConfigPatchOptions,
  ): this;
  /** * Merges source values through `combineConfig`; list form accepts explicit strategies. Returns * this same owner, typed with the merged shape. */ combine<
    S extends readonly IConfigSource[],
  >(...sources: S): ConfigOwner<T & IMergedConfig<S>>;
  combine<S extends readonly IConfigSource[]>(
    sources: S,
    options: IConfigCombineOptions,
  ): ConfigOwner<T & IMergedConfig<S>>;
  /** * Runs writes as one validated commit and watcher notification. Nested batches join the outer * batch; a throw or validation failure restores the previous snapshot. */ batch(
    fn: (owner: this) => void,
  ): this;
  /** Restores the snapshot captured at construction (watchers fire when it differs). */ reset(): this;
  /** Rejects every later write with `CONFIG_READONLY`. Irreversible. */ lock(): this;
  /** * Watches the root or one changed path; returns an idempotent unsubscribe. Listener failures go * to `report`, and writes during notification throw `REENTRANT_CALL`. */ watch(
    listener: (next: IConfigView<T>, prev: IConfigView<T>) => void,
  ): () => void;
  watch<const P extends IConfigOwnerPath<T>>(
    path: P,
    listener: (
      next: IConfigView<IConfigOwnerPathValue<T, P>> | undefined,
      prev: IConfigView<IConfigOwnerPathValue<T, P>> | undefined,
    ) => void,
  ): () => void;
  /** New owner with the same snapshot and options; listeners and lock state are not copied. */ clone(): ConfigOwner<T>;
  /** JSON data of the current snapshot; non-JSON values throw `CONFIG_UNSUPPORTED`. */ toJSON(): IConfigRecord;
