import { withTimeout } from '@migaia/utils/promise'
import { isUtilsTimeoutError } from '@migaia/utils/error'

// 模拟一个 2 秒才返回的查询；真实代码里通常是 fetch(url, { signal })。
function slowQuery(signal: AbortSignal): Promise<string> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => resolve('查询结果'), 2_000)
    signal.addEventListener('abort', () => {
      clearTimeout(timer) // 收到取消，立即停下
      console.log('查询已停止，原因:', signal.reason.code)
      reject(signal.reason)
    })
  })
}

try {
  await withTimeout(({ signal }) => slowQuery(signal), { timeoutMs: 100 })
} catch (error) {
  if (isUtilsTimeoutError(error)) console.log('超时:', error.code, error.timeoutMs)
}

import { createServer } from 'node:http'
import { isUtilsTimeoutError } from '@migaia/utils/error'
import { retry } from '@migaia/utils/promise'

// 一个不稳定的接口：第 1 次请求卡住 2 秒，第 2 次返回 503，第 3 次正常。
let requests = 0
const server = createServer((_request, response) => {
  requests += 1
  if (requests === 1) setTimeout(() => response.end('太慢了'), 2_000)
  else if (requests === 2) response.writeHead(503).end()
  else response.end('订单列表')
}).listen(0)
const { port } = server.address() as { port: number }

const body = await retry(
  async ({ attempt, signal }) => {
    console.log(`第 ${attempt} 次请求`)
    const response = await fetch(`http://localhost:${port}/orders`, { signal })
    if (!response.ok)
      throw Object.assign(new Error(`HTTP ${response.status}`), { status: response.status })
    return response.text()
  },
  {
    maxAttempts: 4,
    attemptTimeoutMs: 300, // 每次最多等 300 毫秒，到点取消这次 fetch
    shouldRetry: (error) =>
      isUtilsTimeoutError(error) || (error as { status?: number }).status! >= 500,
    delay: 100 // 两次请求之间等 100 毫秒
  }
)
console.log('结果:', body)
server.closeAllConnections()
server.close()

