const profileUnavailable = new Error('profile unavailable')
let profileReads = 0
const user = {
  name: 'Ada',
  get profile(): never {
    profileReads += 1
    throw profileUnavailable
  }
}

function readLabel(value: object, key: PropertyKey): string {
