  switch (result.kind) {
    case 'value':
      return result.value
    case 'missing':
      return 'Anonymous'
    case 'failed':
      console.error('property read failed', result.error)
      return 'Unavailable'
  }
}

readLabel(user, 'name') // 'Ada'
readLabel(user, 'email') // 'Anonymous'
readLabel(user, 'profile') // 'Unavailable'
